const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum WorkspaceStatus {\n  PENDING\n  STARTING\n  RUNNING\n  STOPPED\n  FAILED\n}\n\nenum SubscriptionStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELED\n  UNPAID\n}\n\nenum DeploymentStatus {\n  QUEUED\n  BUILDING\n  READY\n  FAILED\n  CANCELED\n}\n\nenum SupportTicketStatus {\n  OPEN\n  PENDING\n  RESOLVED\n  CLOSED\n}\n\nenum OrganizationMembershipState {\n  ACTIVE\n  SUSPENDED\n}\n\nenum CollaborationGroupSource {\n  MANUAL\n  SCIM\n}\n\nenum AccessGrantSubjectType {\n  USER\n  GROUP\n}\n\nenum AccessGrantResourceType {\n  PROJECT\n  ARTIFACT\n  DEPLOYMENT\n  DATASET\n}\n\nenum AccessGrantStatus {\n  PENDING_CONSENT\n  ACTIVE\n  REVOKED\n}\n\nmodel User {\n  id                          String                         @id @default(cuid())\n  email                       String                         @unique\n  name                        String?\n  passwordHash                String?\n  emailVerifiedAt             DateTime?\n  mfaEnabled                  Boolean                        @default(false)\n  mfaSecretCiphertext         String?\n  platformAdmin               Boolean                        @default(false)\n  // BCP-47 primary language tag (e.g. \"en\", \"fr\"). Null when the user\n  // hasn't set a preference; the client falls back to navigator.language\n  // and finally to \"en\". Drives SSR language selection via a cookie set\n  // on session create.\n  language                    String?\n  // IANA timezone name (e.g. \"Europe/Paris\"). Null until the user sets it\n  // in account/IDE settings; the client falls back to\n  // Intl.DateTimeFormat().resolvedOptions().timeZone.\n  timezone                    String?\n  // Free-form per-user preferences blob set from the in-IDE settings panel\n  // (notifications, event logs, feature toggles, profile fields). Shallow\n  // -merged on PATCH so partial updates never clobber unrelated keys.\n  // language/timezone stay first-class columns above because SSR + the SaaS\n  // account-settings route read them directly.\n  preferences                 Json?\n  // Last time the user was active (throttled touch on authenticated requests +\n  // session create). Drives Replit-parity inactivity GC (free accounts inactive\n  // >= 1 year are eligible for deletion; paid exempt). Null until first touch. P8.\n  lastActiveAt                DateTime?\n  createdAt                   DateTime                       @default(now())\n  updatedAt                   DateTime                       @updatedAt\n  accounts                    Account[]\n  sessions                    Session[]\n  memberships                 OrganizationMember[]\n  apiKeys                     ApiKey[]\n  auditLogs                   AuditLog[]\n  adminAuditLogs              AdminAuditLog[]\n  conversations               AiConversation[]\n  supportTickets              SupportTicket[]\n  oauthConnections            OAuthConnection[]\n  emailVerificationTokens     EmailVerificationToken[]\n  passwordResetTokens         PasswordResetToken[]\n  recoveryCodes               MfaRecoveryCode[]\n  projectCollaborations       ProjectCollaborator[]\n  projectActivity             ProjectActivity[]\n  projectSnapshots            ProjectSnapshot[]\n  galleryListings             GalleryListing[]               @relation(\"UserGalleryListings\")\n  projectIdeStateUpdates      ProjectIdeState[]\n  collaborationPresence       CollaborationPresence[]\n  collaborationComments       CollaborationComment[]\n  collaborationShareLinks     ProjectShareLink[]\n  agentMemories               AgentMemory[]\n  agentMemoryPreferences      AgentMemoryPreference[]\n  mcpInstalls                 McpInstall[]\n  mcpUserConfig               McpUserConfig?\n  agentRuns                   AgentRun[]\n  userConnections             UserConnection[]\n  linkedProjectConnections    ProjectConnectionLink[]        @relation(\"LinkedByUser\")\n  configuredOauthAppOverrides OrganizationOAuthAppOverride[] @relation(\"ConfiguredByUser\")\n  integrationFeatureRequests  IntegrationFeatureRequest[]\n  notifications               Notification[]\n  aiMessageFeedback           AiMessageFeedback[]\n  spendLimits                 UserSpendLimit[]\n  agentRoutingCards           AgentRoutingCard[]             @relation(\"AgentRoutingCardAuthor\")\n  runtimeWebSocketTickets     RuntimeWebSocketTicket[]\n  importJobs                  ImportJob[]                    @relation(\"ImportJobActor\")\n  remixStorageSharesConsented RemixStorageShare[]            @relation(\"RemixStorageShareConsentedBy\")\n  rollbackOperations          RollbackIdempotencyRequest[]   @relation(\"RollbackOperationActor\")\n  cloudOperations             CloudOperation[]\n  projectCheckpoints          ProjectCheckpoint[]            @relation(\"ProjectCheckpointCreator\")\n  invitedOrganizationMembers  OrganizationMember[]           @relation(\"OrganizationMemberInviter\")\n  createdOrganizationInvites  OrganizationInvite[]           @relation(\"OrganizationInviteCreator\")\n  accessGrantSubjects         ResourceAccessGrant[]          @relation(\"AccessGrantSubjectUser\")\n  accessGrantsCreated         ResourceAccessGrant[]          @relation(\"AccessGrantCreator\")\n  accessGrantsRevoked         ResourceAccessGrant[]          @relation(\"AccessGrantRevoker\")\n}\n\nmodel Account {\n  id                String   @id @default(cuid())\n  userId            String\n  provider          String\n  providerAccountId String\n  createdAt         DateTime @default(now())\n  user              User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n  @@index([userId])\n}\n\nmodel Session {\n  id             String    @id @default(cuid())\n  userId         String\n  tokenHash      String    @unique\n  refreshHash    String?   @unique\n  expiresAt      DateTime\n  rotatedAt      DateTime?\n  revokedAt      DateTime?\n  lastReauthAt   DateTime?\n  // When set, this session is an admin impersonating another user; value = the\n  // impersonating admin's user id (for audit / UI banner / traceability). P8.\n  impersonatedBy String?\n  ipAddress      String?\n  userAgent      String?\n  createdAt      DateTime  @default(now())\n  user           User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel Organization {\n  id                         String                          @id @default(cuid())\n  slug                       String                          @unique\n  name                       String\n  /// Optional CC address for billing notifications (spend alerts, invoices).\n  billingEmail               String?\n  createdAt                  DateTime                        @default(now())\n  updatedAt                  DateTime                        @updatedAt\n  members                    OrganizationMember[]\n  invites                    OrganizationInvite[]\n  projects                   Project[]\n  billingCustomer            BillingCustomer?\n  subscriptions              Subscription[]\n  usageEvents                UsageEvent[]\n  quotaLedger                QuotaLedger[]\n  quotaOverrides             QuotaOverride[]\n  stripeEvents               StripeEvent[]\n  aiCostLedger               AiCostLedger[]\n  auditLogs                  AuditLog[]\n  abuseEvents                AbuseEvent[]\n  supportTickets             SupportTicket[]\n  featureFlags               FeatureFlag[]\n  apiKeys                    ApiKey[]\n  enterpriseSettings         EnterpriseOrganizationSettings?\n  domains                    VerifiedDomain[]\n  ssoConfigurations          SsoConfiguration[]\n  scimTokens                 ScimToken[]\n  customRoles                CustomRole[]\n  siemWebhooks               SiemWebhook[]\n  projectTemplates           ProjectTemplate[]\n  agentMemories              AgentMemory[]\n  agentMemoryPreferences     AgentMemoryPreference[]\n  mcpInstalls                McpInstall[]\n  agentRuns                  AgentRun[]\n  oauthAppOverrides          OrganizationOAuthAppOverride[]\n  connectorPolicies          OrganizationConnectorPolicy[]\n  integrationFeatureRequests IntegrationFeatureRequest[]\n  creditWallet               CreditWallet?\n  creditLedger               CreditLedger[]\n  creditPacks                CreditPack[]\n  agentCheckpoints           AgentCheckpoint[]\n  userSpendLimits            UserSpendLimit[]\n  importJobs                 ImportJob[]\n  remixStorageSharesAsSource RemixStorageShare[]             @relation(\"RemixStorageShareSourceOrganization\")\n  remixStorageSharesAsTarget RemixStorageShare[]             @relation(\"RemixStorageShareTargetOrganization\")\n  cloudTenant                CloudTenant?\n  collaborationGroups        CollaborationGroup[]\n  resourceAccessGrants       ResourceAccessGrant[]\n}\n\nmodel OrganizationMember {\n  id               String                      @id @default(cuid())\n  organizationId   String\n  userId           String\n  roleId           String\n  state            OrganizationMembershipState @default(ACTIVE)\n  invitedByUserId  String?\n  joinedAt         DateTime                    @default(now())\n  createdAt        DateTime                    @default(now())\n  organization     Organization                @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  user             User                        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  invitedBy        User?                       @relation(\"OrganizationMemberInviter\", fields: [invitedByUserId], references: [id], onDelete: SetNull)\n  role             Role                        @relation(fields: [roleId], references: [id])\n  groupMemberships CollaborationGroupMember[]\n\n  @@unique([organizationId, userId])\n  @@unique([organizationId, id])\n  @@index([userId])\n  @@index([roleId])\n  @@index([invitedByUserId])\n}\n\nmodel OrganizationInvite {\n  id              String       @id @default(cuid())\n  organizationId  String\n  email           String\n  roleId          String\n  tokenHash       String       @unique\n  expiresAt       DateTime\n  acceptedAt      DateTime?\n  createdByUserId String?\n  createdAt       DateTime     @default(now())\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  role            Role         @relation(fields: [roleId], references: [id])\n  createdBy       User?        @relation(\"OrganizationInviteCreator\", fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  @@index([organizationId])\n  @@index([createdByUserId])\n}\n\nmodel Role {\n  id          String               @id @default(cuid())\n  key         String               @unique\n  name        String\n  system      Boolean              @default(false)\n  permissions RolePermission[]\n  members     OrganizationMember[]\n  invites     OrganizationInvite[]\n}\n\nmodel Permission {\n  id          String           @id @default(cuid())\n  key         String           @unique\n  description String?\n  roles       RolePermission[]\n}\n\nmodel RolePermission {\n  roleId       String\n  permissionId String\n  role         Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission   Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, permissionId])\n}\n\nmodel Project {\n  id                       String                       @id @default(cuid())\n  organizationId           String\n  name                     String\n  slug                     String\n  description              String?\n  sourceType               String                       @default(\"blank\")\n  templateName             String?\n  gitRepositoryUrl         String?\n  gitDefaultBranch         String?\n  persistentVolumeClaim    String?\n  thumbnailUrl             String?\n  thumbnailUpdatedAt       DateTime?\n  deletedAt                DateTime?\n  createdAt                DateTime                     @default(now())\n  updatedAt                DateTime                     @updatedAt\n  organization             Organization                 @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  environments             ProjectEnvironment[]\n  envVars                  ProjectEnvVar[]\n  secrets                  ProjectSecret[]\n  collaborators            ProjectCollaborator[]\n  activity                 ProjectActivity[]\n  templates                ProjectTemplate[]            @relation(\"ProjectTemplates\")\n  galleryListings          GalleryListing[]             @relation(\"ProjectGalleryListings\")\n  workspaces               Workspace[]\n  snapshots                ProjectSnapshot[]\n  manifestRevisions        ProjectManifestRevision[]\n  storageObjects           ProjectStorageObject[]\n  deployments              Deployment[]\n  reservedVmBillingPeriods ReservedVmBillingPeriod[]\n  rollbackOperations       RollbackIdempotencyRequest[]\n  fileSnapshots            FileSnapshot[]\n  conversations            AiConversation[]\n  ideState                 ProjectIdeState?\n  collaborationPresence    CollaborationPresence[]\n  collaborationComments    CollaborationComment[]\n  shareLinks               ProjectShareLink[]\n  agentMemories            AgentMemory[]\n  agentMemoryPreferences   AgentMemoryPreference[]\n  agentPatchProposals      AgentPatchProposal[]\n  connectionLinks          ProjectConnectionLink[]\n  databaseInstances        DatabaseInstance[]\n  skills                   ProjectSkill[]\n  repairEvents             AgentRepairEvent[]\n  slugRedirects            ProjectSlugRedirect[]\n  runtimeWebSocketTickets  RuntimeWebSocketTicket[]\n  importJobs               ImportJob[]                  @relation(\"ImportJobTarget\")\n  targetRemixJobs          RemixJob[]                   @relation(\"RemixJobTarget\")\n  sourceRemixShares        RemixStorageShare[]          @relation(\"RemixStorageShareSourceProject\")\n  targetRemixShares        RemixStorageShare[]          @relation(\"RemixStorageShareTargetProject\")\n  cloudBinding             CloudProjectBinding?\n  checkpoints              ProjectCheckpoint[]\n\n  @@unique([organizationId, slug])\n  @@index([organizationId])\n}\n\n// F13: preserves an old project slug after a rename so the previous canonical\n// URL keeps redirecting to the current one until `expiresAt` (30 days). Purely\n// additive: an `oldSlug` snapshot with an FK back to the project so rows cascade\n// away when the project is hard-deleted.\nmodel ProjectSlugRedirect {\n  id        String   @id @default(cuid())\n  projectId String\n  oldSlug   String\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, oldSlug])\n  @@index([oldSlug])\n}\n\nmodel AgentMemory {\n  id                  String                @id @default(cuid())\n  userId              String\n  organizationId      String?\n  projectId           String?\n  sessionId           String?\n  scope               String\n  content             String\n  summary             String\n  embedding           Unsupported(\"vector\")\n  embeddingModel      String\n  embeddingDimensions Int                   @default(1536)\n  metadata            Json                  @default(\"{}\")\n  memoryType          String                @default(\"semantic\")\n  tags                String[]              @default([])\n  references          String[]              @default([])\n  importance          Float                 @default(0.5)\n  source              String\n  createdAt           DateTime              @default(now())\n  updatedAt           DateTime              @updatedAt\n  lastUsedAt          DateTime?\n  expiresAt           DateTime?\n  archivedAt          DateTime?\n  accessCount         Int                   @default(0)\n  user                User                  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  organization        Organization?         @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  project             Project?              @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([userId, scope, updatedAt])\n  @@index([memoryType, updatedAt])\n  @@index([organizationId, updatedAt])\n  @@index([projectId, updatedAt])\n  @@index([sessionId, updatedAt])\n}\n\nmodel AgentMemoryPreference {\n  id             String        @id @default(cuid())\n  userId         String\n  organizationId String?\n  projectId      String?\n  enabled        Boolean       @default(true)\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n  user           User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  organization   Organization? @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  project        Project?      @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([userId, updatedAt])\n  @@index([organizationId, updatedAt])\n  @@index([projectId, updatedAt])\n}\n\nmodel ProjectIdeState {\n  projectId       String   @id\n  state           Json\n  version         Int      @default(1)\n  updatedByUserId String?\n  updatedAt       DateTime @updatedAt\n  createdAt       DateTime @default(now())\n  project         Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  updatedBy       User?    @relation(fields: [updatedByUserId], references: [id], onDelete: SetNull)\n}\n\n// Persists the AI-generated patch review queue across workbench reloads.\n// Terminal status proposals (accepted, rejected, reverted) are hard-deleted\n// because the audit trail lives in ProjectActivity; this table only holds\n// proposals the user still has to decide on. The id is the existing\n// \"artifactId:actionId\" composite the streaming runner already uses, so the\n// nanostore key and the row id line up 1:1.\nmodel AgentPatchProposal {\n  id              String   @id\n  projectId       String\n  artifactId      String\n  messageId       String\n  actionId        String\n  filePath        String\n  relativePath    String\n  originalContent String\n  proposedContent String\n  hunks           Json\n  status          String\n  error           String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n  project         Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId, status])\n  @@index([projectId, updatedAt])\n}\n\n// Durable history of the agent's AST self-repair pipeline: each time a streamed\n// file fails validation and the agent retries (regenerates) it, the outcome is\n// recorded here so the IDE can show a review UI of auto-repairs/errors. Unlike\n// AgentPatchProposal (a transient working queue, hard-deleted on decision), this\n// is an append-only audit log. Additive + inert until the IDE records/reads it.\nmodel AgentRepairEvent {\n  id              String   @id @default(cuid())\n  projectId       String\n  messageId       String?\n  artifactId      String?\n  actionId        String?\n  relativePath    String\n  attempt         Int      @default(1)\n  // 'repaired' (validation passed after retry) | 'failed' (this attempt failed) |\n  // 'gave_up' (retry budget exhausted, original written best-effort)\n  outcome         String\n  validationError String?\n  repairError     String?\n  createdAt       DateTime @default(now())\n  project         Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId, createdAt])\n}\n\n// Per-project enable/disable overrides for the builtin Skills catalog (Replit\n// parity). The catalog itself is a static, code-owned list (skills-catalog.ts);\n// this table only stores the sparse set of projects that toggled a skill away\n// from its default. Absent row => the skill is at its catalog default. skillId\n// is the catalog slug. Unique per (project, skill).\nmodel ProjectSkill {\n  id        String   @id @default(cuid())\n  projectId String\n  skillId   String\n  enabled   Boolean\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, skillId])\n  @@index([projectId])\n}\n\n// Installable GitHub-repo skills (F#27). A row records a PUBLIC GitHub skill repo\n// that a project or its workspace has installed, plus the instructions fetched\n// from the repo at install time. Polymorphic scope: scope='project' => scopeId is\n// a projectId; scope='workspace' => scopeId is a workspaceId. No FK (polymorphic),\n// so orphan cleanup is by the owning route. Layered ON TOP of the builtin catalog\n// (ProjectSkill) — that table is untouched. Unique per (scope, scopeId, ownerRepo).\nmodel InstalledSkill {\n  id                String   @id @default(cuid())\n  scope             String\n  scopeId           String\n  ownerRepo         String\n  name              String\n  description       String\n  instructions      String\n  homepageUrl       String?\n  enabled           Boolean  @default(true)\n  installedByUserId String?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  // RPL-SK-001.3/.4 — provenance + security-audit + revoke state.\n  // origin: where the skill came from ('catalog' | 'github' | 'workspace-file' | 'builtin').\n  origin          String    @default(\"github\")\n  // sha256 of the audited disclosed surface (body + resources) — provenance integrity.\n  contentHash     String?\n  // Latest audit verdict: 'approved' | 'quarantined' | 'rejected'. A 'rejected' skill\n  // is never persisted enabled; a 'quarantined' one is disabled pending approval.\n  auditVerdict    String?\n  // JSON array of AuditFinding for the UI's audit panel.\n  auditFindings   String?\n  auditedAt       DateTime?\n  // Parsed interop-manifest fields (agentskills.io) when the skill is a real SKILL.md.\n  manifestName    String?\n  // JSON array of {path, kind, bytes} for progressive-disclosure L3 resources.\n  resourcesJson   String?\n  // Revoke is distinct from uninstall: the row stays for audit but is hard-disabled\n  // and cannot be re-enabled until re-installed.\n  revokedAt       DateTime?\n  revokedByUserId String?\n  revokeReason    String?\n\n  @@unique([scope, scopeId, ownerRepo])\n  @@index([scope, scopeId])\n  @@index([ownerRepo])\n}\n\n// Append-only audit journal for interoperable Agent Skills (RPL-SK-001.3). Every\n// consequential skill event — an install being approved/quarantined/REJECTED, a\n// manual approval, an enable/disable, a revoke, an uninstall — writes one immutable\n// row here so the security history of a project's skills is fully reconstructable.\n// No FK (polymorphic scope like InstalledSkill); never updated after insert.\nmodel SkillAuditEvent {\n  id           String   @id @default(cuid())\n  scope        String\n  scopeId      String\n  ownerRepo    String\n  // 'install-approved' | 'install-quarantined' | 'install-rejected' | 'approve'\n  // | 'revoke' | 'enable' | 'disable' | 'uninstall'\n  action       String\n  verdict      String?\n  findingsJson String?\n  contentHash  String?\n  actorUserId  String?\n  createdAt    DateTime @default(now())\n\n  @@index([scope, scopeId])\n  @@index([ownerRepo])\n  @@index([createdAt])\n}\n\nmodel ProjectEnvironment {\n  id        String   @id @default(cuid())\n  projectId String\n  name      String\n  createdAt DateTime @default(now())\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, name])\n}\n\nmodel ProjectSecret {\n  id             String   @id @default(cuid())\n  projectId      String\n  key            String\n  valueHash      String\n  valueEncrypted String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  project        Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, key])\n}\n\nmodel ProjectEnvVar {\n  id        String   @id @default(cuid())\n  projectId String\n  key       String\n  value     String\n  // Deployment scope this value applies to: development | preview | production.\n  // Defaults to \"production\" so every pre-scope row keeps its existing meaning.\n  scope     String   @default(\"production\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, key, scope])\n}\n\nmodel ProjectCollaborator {\n  id        String    @id @default(cuid())\n  projectId String\n  userId    String\n  roleKey   String\n  // When set, the grant is ignored after this instant. A time-limited share\n  // link writes its own expiry here so redeeming it no longer confers permanent\n  // access. Null = no expiry (direct invites).\n  expiresAt DateTime?\n  createdAt DateTime  @default(now())\n  project   Project   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, userId])\n  @@index([userId])\n}\n\nmodel ProjectActivity {\n  id          String   @id @default(cuid())\n  projectId   String\n  actorUserId String?\n  action      String\n  metadata    Json?\n  createdAt   DateTime @default(now())\n  project     Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  actor       User?    @relation(fields: [actorUserId], references: [id], onDelete: SetNull)\n\n  @@index([projectId])\n  @@index([actorUserId])\n}\n\nmodel CollaborationPresence {\n  id             String   @id @default(cuid())\n  projectId      String\n  userId         String\n  sessionId      String\n  status         String   @default(\"online\")\n  filePath       String?\n  cursor         Json?\n  selection      Json?\n  mode           String   @default(\"editing\")\n  terminalAccess Boolean  @default(false)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n  project        Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, sessionId])\n  @@index([projectId, updatedAt])\n  @@index([userId])\n}\n\nmodel CollaborationComment {\n  id         String    @id @default(cuid())\n  projectId  String\n  userId     String\n  filePath   String?\n  line       Int?\n  selection  Json?\n  body       String\n  resolvedAt DateTime?\n  createdAt  DateTime  @default(now())\n  project    Project   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([projectId, createdAt])\n  @@index([userId])\n}\n\nmodel ProjectShareLink {\n  id              String    @id @default(cuid())\n  projectId       String\n  tokenHash       String    @unique\n  roleKey         String\n  expiresAt       DateTime\n  createdByUserId String?\n  revokedAt       DateTime?\n  createdAt       DateTime  @default(now())\n  project         Project   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  createdBy       User?     @relation(fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  @@index([projectId, expiresAt])\n}\n\n/// A tenant-scoped group. SCIM groups are written only through the authenticated\n/// SCIM surface; interactive routes may only create and mutate MANUAL groups.\n/// Deletion is soft so grants and the audit trail remain explainable.\nmodel CollaborationGroup {\n  id             String                     @id @default(cuid())\n  organizationId String\n  name           String\n  normalizedName String\n  source         CollaborationGroupSource   @default(MANUAL)\n  externalId     String?\n  deletedAt      DateTime?\n  createdAt      DateTime                   @default(now())\n  updatedAt      DateTime                   @updatedAt\n  organization   Organization               @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  members        CollaborationGroupMember[]\n  accessGrants   ResourceAccessGrant[]\n\n  @@unique([organizationId, id])\n  @@index([organizationId, deletedAt, id])\n}\n\n/// The composite foreign keys make cross-tenant group membership impossible at\n/// the database boundary: both the group and the OrganizationMember must belong\n/// to this exact organization.\nmodel CollaborationGroupMember {\n  id             String             @id @default(cuid())\n  organizationId String\n  groupId        String\n  membershipId   String\n  createdAt      DateTime           @default(now())\n  group          CollaborationGroup @relation(fields: [organizationId, groupId], references: [organizationId, id], onDelete: Cascade)\n  membership     OrganizationMember @relation(fields: [organizationId, membershipId], references: [organizationId, id], onDelete: Cascade)\n\n  @@unique([groupId, membershipId])\n  @@index([organizationId, membershipId])\n}\n\n/// A resource-scoped authorization edge. External USER subjects start in\n/// PENDING_CONSENT and confer no access until the subject accepts. Every grant\n/// expires, every revocation is retained, and retry identity is request-hashed.\nmodel ResourceAccessGrant {\n  id               String                  @id @default(cuid())\n  organizationId   String\n  subjectType      AccessGrantSubjectType\n  subjectUserId    String?\n  subjectGroupId   String?\n  resourceType     AccessGrantResourceType\n  resourceId       String\n  roleKey          String\n  status           AccessGrantStatus\n  expiresAt        DateTime\n  acceptedAt       DateTime?\n  consentVersion   String?\n  grantedByUserId  String\n  revokedAt        DateTime?\n  revokedByUserId  String?\n  revocationReason String?\n  idempotencyKey   String?\n  requestHash      String\n  createdAt        DateTime                @default(now())\n  updatedAt        DateTime                @updatedAt\n  organization     Organization            @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  subjectUser      User?                   @relation(\"AccessGrantSubjectUser\", fields: [subjectUserId], references: [id], onDelete: Cascade)\n  subjectGroup     CollaborationGroup?     @relation(fields: [organizationId, subjectGroupId], references: [organizationId, id], onDelete: Restrict)\n  grantedBy        User                    @relation(\"AccessGrantCreator\", fields: [grantedByUserId], references: [id], onDelete: Restrict)\n  revokedBy        User?                   @relation(\"AccessGrantRevoker\", fields: [revokedByUserId], references: [id], onDelete: SetNull)\n\n  @@unique([organizationId, idempotencyKey])\n  @@index([resourceType, resourceId, status, expiresAt])\n  @@index([subjectUserId, status, expiresAt])\n  @@index([subjectGroupId, status, expiresAt])\n  @@index([organizationId, createdAt, id])\n}\n\nmodel ProjectTemplate {\n  id              String       @id @default(cuid())\n  sourceProjectId String\n  organizationId  String\n  name            String\n  description     String?\n  createdAt       DateTime     @default(now())\n  sourceProject   Project      @relation(\"ProjectTemplates\", fields: [sourceProjectId], references: [id], onDelete: Cascade)\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId])\n}\n\nmodel Workspace {\n  id               String                    @id @default(cuid())\n  projectId        String\n  name             String\n  status           WorkspaceStatus           @default(PENDING)\n  runtimeMode      String\n  // P2d dev/prod split: 'development' (the editable workspace) or 'production'\n  // (the checkout created when a deployment is published). Existing rows\n  // backfill to 'development'. Not unique — a project keeps multiple dev\n  // workspaces (primary + secondary agent-run checkouts); the prod checkout\n  // is the single workspace with environment='production'.\n  environment      String                    @default(\"development\")\n  // Filesystem path (relative to the project storage root) for this\n  // workspace's isolated git working tree. Allocated when the workspace\n  // is created so each branch / agent run can have its own checkout\n  // without colliding with other workspaces of the same project.\n  gitPath          String?\n  // Remote URL for this workspace's git working tree. Workspaces can point\n  // at different remotes (e.g. an agent run targets a personal fork while\n  // the primary workspace tracks the upstream project), so we store the\n  // remote here instead of falling back to Project.gitRepositoryUrl for\n  // every workspace. Nullable: a fresh workspace inherits the project-level\n  // remote until the user explicitly configures one.\n  gitRepositoryUrl String?\n  createdAt        DateTime                  @default(now())\n  updatedAt        DateTime                  @updatedAt\n  project          Project                   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  sessions         WorkspaceSession[]\n  ports            WorkspacePort[]\n  snapshots        FileSnapshot[]\n  ideState         WorkspaceIdeState?\n  readinessBeacons PreviewReadinessBeacon[]\n  lifecycleEvents  WorkspaceLifecycleEvent[]\n  postMortems      WorkspacePostMortem[]\n\n  @@index([projectId])\n}\n\n// Workspace-scoped IDE state (open tabs, file manifest, scroll positions, …).\n// Mirrors ProjectIdeState 1:1 but keyed by workspace so each working tree can\n// keep its own editor cursor, file tree, and unsaved buffers. listFiles falls\n// back to the project-level state when a workspace has no entry yet, which\n// keeps backward compatibility with workspaces created before this table\n// existed.\nmodel WorkspaceIdeState {\n  workspaceId     String    @id\n  state           Json\n  version         Int       @default(1)\n  updatedByUserId String?\n  updatedAt       DateTime  @updatedAt\n  createdAt       DateTime  @default(now())\n  workspace       Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n}\n\nmodel WorkspaceSession {\n  id          String          @id @default(cuid())\n  workspaceId String\n  userId      String?\n  status      WorkspaceStatus @default(STARTING)\n  startedAt   DateTime        @default(now())\n  stoppedAt   DateTime?\n  workspace   Workspace       @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId])\n  // Presence-cleanup sweeps by userId (nullable); without this it full-scanned.\n  @@index([userId])\n}\n\nmodel WorkspacePort {\n  id          String    @id @default(cuid())\n  workspaceId String\n  port        Int\n  url         String?\n  protocol    String    @default(\"http\")\n  createdAt   DateTime  @default(now())\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, port])\n}\n\nmodel FileSnapshot {\n  id          String     @id @default(cuid())\n  projectId   String\n  workspaceId String?\n  path        String\n  contentHash String\n  sizeBytes   Int\n  metadata    Json?\n  createdAt   DateTime   @default(now())\n  project     Project    @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  workspace   Workspace? @relation(fields: [workspaceId], references: [id], onDelete: SetNull)\n\n  @@index([projectId, path])\n}\n\nmodel ProjectSnapshot {\n  id              String   @id @default(cuid())\n  projectId       String\n  label           String?\n  kind            String   @default(\"manual\")\n  manifest        Json\n  storageKey      String?\n  byteLength      Int?\n  createdByUserId String?\n  // Association used to pair a snapshot to the chat checkpoint that produced it.\n  // Populated for AI \"before-ai-change\" snapshots; NULL for manual/legacy rows.\n  // turnIndex is the assistant-turn ordinal within the conversation at the time\n  // the snapshot was taken (the first snapshot of a turn has the smallest\n  // createdAt). See migration 0046_snapshot_checkpoint_assoc.\n  conversationId  String?\n  turnIndex       Int?\n  createdAt       DateTime @default(now())\n  project         Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  createdBy       User?    @relation(fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  @@index([projectId])\n  @@index([createdByUserId])\n  @@index([conversationId, turnIndex])\n}\n\n// P0-EX-08: append-only, integrity-bound ProjectManifest history. The latest\n// manifestVersion is the project's component/artifact/scope source of truth;\n// consumers re-canonicalize `manifest` and verify `digest` before acting.\nmodel ProjectManifestRevision {\n  id              String   @id @default(cuid())\n  projectId       String\n  schemaVersion   Int\n  manifestVersion Int\n  digest          String\n  manifest        Json\n  createdByUserId String?\n  createdAt       DateTime @default(now())\n  project         Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, manifestVersion])\n  @@unique([projectId, digest])\n  @@index([projectId, createdAt])\n}\n\nmodel ProjectStorageObject {\n  id            String   @id @default(cuid())\n  projectId     String?\n  key           String   @unique\n  kind          String\n  contentBase64 String\n  byteLength    Int\n  contentHash   String\n  createdAt     DateTime @default(now())\n  project       Project? @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId])\n  @@index([kind])\n  @@index([createdAt])\n}\n\nmodel Deployment {\n  id                             String                    @id @default(cuid())\n  projectId                      String\n  workspaceId                    String?\n  environmentId                  String?\n  environmentName                String                    @default(\"preview\")\n  status                         DeploymentStatus          @default(QUEUED)\n  provider                       String\n  url                            String?\n  previewUrl                     String?\n  productionUrl                  String?\n  framework                      String?\n  buildCommand                   String?\n  outputDirectory                String?\n  branch                         String?\n  commitSha                      String?\n  customDomain                   String?\n  logs                           Json                      @default(\"[]\")\n  metadata                       Json                      @default(\"{}\")\n  rolledBackFromId               String?\n  // P2d dev/prod split: when a preview/staging deployment is published to\n  // production, the new production deployment links back to its source here.\n  parentDeploymentId             String?\n  // Replit-parity deploy metering idempotency marker: set once the deployment is\n  // metered (mirrors WorkspaceRuntime.lastMeteredAt) so a re-reconcile never\n  // double-charges. Dormant/SHADOW until BILLING_CREDITS_ENABLED. See metering-service.ts.\n  lastMeteredAt                  DateTime?\n  // Machine size the user picked at publish (rate-card key, e.g. 'dedicated-1').\n  // Applied verbatim as the runtime pod's requests==limits and used to price\n  // compute metering — the machine you picked is the machine you pay for.\n  machineSize                    String                    @default(\"shared-0.5\")\n  // Reserved VM is a distinct always-on lifecycle, not an Autoscale size.\n  // runtimeVersion fences every in-place lifecycle/tier change.\n  runtimeKind                    String                    @default(\"autoscale\")\n  runtimeVersion                 Int                       @default(0)\n  reservedVmTier                 String?\n  reservedVmPriceCents           Int?\n  reservedVmTermsVersion         String?\n  reservedVmRateCardVersion      Int?\n  reservedVmBillingReservationId String?                   @unique\n  // Calendar-month renewal state. All deadlines are derived from PostgreSQL\n  // time; STOP_REQUIRED is a durable instruction to stop compute only.\n  reservedVmBillingState         String?\n  reservedVmCurrentPeriodStart   DateTime?\n  reservedVmNextChargeAt         DateTime?\n  reservedVmGraceEndsAt          DateTime?\n  reservedVmStopRequestedAt      DateTime?\n  // Stable claim retained across image, tier and runtime-kind changes.\n  persistentStorageClaim         String?\n  // Exact immutable DeploymentAccessPolicy version enforced by both s-* and\n  // d-* edge paths. The database default exists only for rolling compatibility;\n  // the edge resolves the matching policy row and denies when it is absent.\n  accessPolicyVersion            Int                       @default(1)\n  startedAt                      DateTime?\n  finishedAt                     DateTime?\n  canceledAt                     DateTime?\n  createdAt                      DateTime                  @default(now())\n  updatedAt                      DateTime                  @updatedAt\n  project                        Project                   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  environment                    DeploymentEnvironment?    @relation(fields: [environmentId], references: [id])\n  reservedVmBillingPeriods       ReservedVmBillingPeriod[]\n\n  @@index([projectId])\n  @@index([projectId, workspaceId])\n  @@index([projectId, environmentName])\n  @@index([projectId, status])\n}\n\n// Durable saga for Reserved VM create/change. PostgreSQL clock leases and the\n// expected runtimeVersion fence make a crashed worker resumable without two\n// callers billing or applying the same transition concurrently.\nmodel ReservedVmOperation {\n  id                     String    @id @default(cuid())\n  projectId              String\n  deploymentId           String\n  organizationId         String\n  actorUserId            String?\n  idempotencyKey         String\n  requestHash            String\n  kind                   String\n  status                 String    @default(\"PENDING\")\n  phase                  String    @default(\"RESERVED\")\n  fromRuntimeKind        String?\n  fromTier               String?\n  targetRuntimeKind      String\n  targetTier             String?\n  targetMachineSize      String\n  targetPriceCents       Int\n  billingAmountCents     Int\n  termsVersion           String\n  rateCardVersion        Int\n  expectedRuntimeVersion Int\n  leaseOwner             String?\n  leaseExpiresAt         DateTime?\n  fencingToken           Int       @default(0)\n  billingReservationId   String?   @unique\n  response               Json?\n  errorCode              String?\n  errorMessage           String?\n  completedAt            DateTime?\n  createdAt              DateTime  @default(now())\n  updatedAt              DateTime  @updatedAt\n\n  @@unique([projectId, idempotencyKey])\n  @@index([deploymentId, createdAt])\n  @@index([status, leaseExpiresAt])\n}\n\n// One immutable price snapshot per Reserved VM calendar-month period. A worker\n// may retry a DUE/PAST_DUE row, but (deploymentId, periodStart), the fenced\n// lease, and the canonical LedgerReservation make settlement exactly-once.\nmodel ReservedVmBillingPeriod {\n  id                    String     @id @default(cuid())\n  projectId             String\n  deploymentId          String\n  organizationId        String\n  periodStart           DateTime\n  periodEnd             DateTime\n  tier                  String\n  priceCents            Int\n  termsVersion          String\n  rateCardVersion       Int\n  status                String     @default(\"DUE\")\n  attemptCount          Int        @default(0)\n  reservationGeneration Int        @default(0)\n  leaseOwner            String?\n  leaseExpiresAt        DateTime?\n  fencingToken          Int        @default(0)\n  billingReservationId  String?    @unique\n  graceEndsAt           DateTime?\n  stopRequestedAt       DateTime?\n  settledAt             DateTime?\n  lastErrorCode         String?\n  lastErrorMessage      String?\n  createdAt             DateTime   @default(now())\n  updatedAt             DateTime   @updatedAt\n  project               Project    @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  deployment            Deployment @relation(fields: [deploymentId], references: [id], onDelete: Cascade)\n\n  @@unique([deploymentId, periodStart])\n  @@index([status, leaseExpiresAt])\n  @@index([organizationId, status])\n  @@index([deploymentId, status])\n}\n\nmodel DeploymentEnvironment {\n  id          String       @id @default(cuid())\n  name        String       @unique\n  deployments Deployment[]\n}\n\n// P0-V3-08 deployment rollback manifest: one IMMUTABLE row appended per successful\n// publish. It captures everything a DETERMINISTIC rollback needs so a published\n// deployment can be restored to its previous version for real — independent of any\n// live runtime/snapshot state. `deploymentId` is a plain pointer with NO FK on\n// purpose: the manifest OUTLIVES the deployment row (a deployment can be pruned but\n// its release must remain rollback-addressable). `version` is monotonic per\n// (projectId, environment) so N-1 is unambiguous. A rollback that finds no previous\n// manifest — or an artifact whose bytes no longer match `artifactDigest` — MUST fail\n// closed rather than serve a blind/stale rollback.\nmodel ReleaseManifest {\n  id           String @id @default(cuid())\n  projectId    String\n  deploymentId String\n  environment  String @default(\"preview\")\n  version      Int\n  provider     String\n\n  // 'static-snapshot' (artifactDigest = sha256 of the served bundle bytes) or\n  // 'server-image' (artifactDigest = the image sha256, artifactRef = bare AR ref).\n  artifactKind   String\n  artifactRef    String\n  artifactDigest String\n\n  // Declared, never faked — NULL when the pipeline doesn't emit it:\n  //  storeGeneration  = the ecode.lock Nix generation the release pinned (server)\n  //  configDigest     = sha256 fingerprint of the effective env/config at publish\n  //  dbMigrationPoint = latest applied DB migration marker at publish (RECORDED for\n  //                     compatibility checks; image rollback never reverts the DB)\n  storeGeneration  String?\n  configDigest     String?\n  dbMigrationPoint String?\n\n  // I-AUTH-1: the access policy is part of release identity. Rollback restores\n  // this exact version rather than inheriting a later/less restrictive mode.\n  accessPolicyVersion Int @default(1)\n\n  createdAt DateTime @default(now())\n\n  @@unique([projectId, environment, version])\n  @@index([projectId, environment])\n  @@index([deploymentId])\n}\n\n// Durable execution + response ledger for POST\n// /projects/:projectId/deployments/rollback-to-previous. The row is both the\n// project-scoped idempotency authority and the DB-clock lease/fencing authority\n// for every rollback side effect. A replica may steal an orphan only after the\n// lease expires; the old fence can no longer mutate or publish afterwards.\nmodel RollbackIdempotencyRequest {\n  id                      String    @id @default(cuid())\n  projectId               String\n  actorUserId             String?\n  idempotencyKey          String\n  requestFingerprint      String\n  environment             String\n  status                  String    @default(\"IN_PROGRESS\")\n  phase                   String    @default(\"CLAIMED\")\n  leaseOwner              String?\n  leaseExpiresAt          DateTime?\n  fencingToken            Int       @default(1)\n  effectFencingToken      Int?\n  deploymentId            String?   @unique\n  expectedHeadVersion     Int?\n  previousManifestId      String?\n  projectManifestDigest   String?\n  responseStatus          Int?\n  responseContentLanguage String?\n  responseBody            Json?\n  completedAt             DateTime?\n  createdAt               DateTime  @default(now())\n  updatedAt               DateTime  @updatedAt\n  project                 Project   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  actor                   User?     @relation(\"RollbackOperationActor\", fields: [actorUserId], references: [id], onDelete: SetNull)\n\n  @@unique([projectId, idempotencyKey])\n  @@index([actorUserId, status])\n  @@index([status, leaseExpiresAt])\n  @@index([projectId, environment, status])\n  @@index([previousManifestId])\n}\n\n// Immutable, monotonic access policy history per project/environment. A change\n// inserts a new row and atomically advances Deployment.accessPolicyVersion.\nmodel DeploymentAccessPolicy {\n  id              String   @id @default(cuid())\n  projectId       String\n  environment     String\n  version         Int\n  mode            String\n  revision        String   @unique\n  passwordHash    String?\n  createdByUserId String?\n  createdAt       DateTime @default(now())\n\n  @@unique([projectId, environment, version])\n  @@index([projectId, environment, createdAt])\n}\n\n// One-shot capability used to move an already-authorized identity from the web\n// origin to a dedicated deployment origin. Only tokenHash is persisted.\nmodel DeploymentAccessExchangeTicket {\n  id             String    @id @default(cuid())\n  deploymentId   String\n  userId         String\n  policyVersion  Int\n  policyRevision String\n  tokenHash      String    @unique\n  expiresAt      DateTime\n  consumedAt     DateTime?\n  createdAt      DateTime  @default(now())\n\n  @@index([deploymentId, expiresAt])\n  @@index([userId, expiresAt])\n}\n\n// Versioned Rate Card: the priced catalogue (machine sizes, compute-unit and\n// request rates) served to the app and stamped on every metering event. A\n// price change INSERTS a new version and flips `active` — history is never\n// mutated, so past usage events stay auditable against the card that priced\n// them. Seeded with version 1 (= packages/billing BUILTIN_RATE_CARD).\nmodel RateCard {\n  id          String   @id @default(cuid())\n  version     Int      @unique\n  active      Boolean  @default(false)\n  data        Json\n  effectiveAt DateTime @default(now())\n  createdAt   DateTime @default(now())\n\n  @@index([active])\n}\n\nmodel AuditLog {\n  id             String        @id @default(cuid())\n  organizationId String?\n  actorUserId    String?\n  action         String\n  resourceType   String\n  resourceId     String?\n  metadata       Json?\n  ipAddress      String?\n  createdAt      DateTime      @default(now())\n  organization   Organization? @relation(fields: [organizationId], references: [id], onDelete: SetNull)\n  actor          User?         @relation(fields: [actorUserId], references: [id], onDelete: SetNull)\n\n  @@index([organizationId])\n  @@index([actorUserId])\n  // SIEM delivery keyset-paginates WHERE organizationId ORDER BY (createdAt, id)\n  // every 5 min; without this composite it full-scanned + sorted the org's logs.\n  @@index([organizationId, createdAt, id])\n}\n\n/// F23: operator resolution overlay for security events. Security events are\n/// DERIVED from immutable AuditLog rows (auth/security/mfa actions); this table\n/// carries the mutable resolution state (resolved + an operator note) keyed by\n/// the audit-log id, without mutating the append-only audit trail. Additive-only.\nmodel SecurityEventResolution {\n  id               String   @id @default(cuid())\n  auditLogId       String   @unique\n  resolved         Boolean  @default(true)\n  note             String?\n  resolvedByUserId String?\n  resolvedAt       DateTime @default(now())\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@index([auditLogId])\n}\n\nmodel AdminAuditLog {\n  id          String   @id @default(cuid())\n  actorUserId String?\n  action      String\n  metadata    Json?\n  ipAddress   String?\n  createdAt   DateTime @default(now())\n  actor       User?    @relation(fields: [actorUserId], references: [id], onDelete: SetNull)\n}\n\nmodel BillingCustomer {\n  id             String       @id @default(cuid())\n  organizationId String       @unique\n  provider       String\n  externalId     String\n  createdAt      DateTime     @default(now())\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, externalId])\n}\n\nmodel Subscription {\n  id                 String             @id @default(cuid())\n  organizationId     String\n  planId             String\n  externalId         String?            @unique\n  status             SubscriptionStatus\n  cancelAtPeriodEnd  Boolean            @default(false)\n  trialEndsAt        DateTime?\n  currentPeriodStart DateTime?\n  currentPeriodEnd   DateTime?\n  createdAt          DateTime           @default(now())\n  updatedAt          DateTime           @updatedAt\n  // Stripe `event.created` of the latest applied subscription event. Used to drop\n  // out-of-order webhook deliveries (Stripe does not guarantee ordering) that\n  // would otherwise overwrite newer plan/seat/status state with stale data.\n  lastStripeEventAt  DateTime?\n  organization       Organization       @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  plan               Plan               @relation(fields: [planId], references: [id])\n\n  @@index([organizationId])\n}\n\nmodel Plan {\n  id                   String         @id @default(cuid())\n  key                  String         @unique\n  name                 String\n  monthlyCents         Int\n  limits               Json\n  // Replit-parity additions (nullable → no behaviour change until populated):\n  // annual price (effective discount) and the per-plan monthly credit grant in\n  // USD cents. `stripePriceId` stays = the monthly price for backward compat;\n  // the new *MonthlyId/*AnnualId columns are populated once annual products exist.\n  annualCents          Int?\n  includedCreditCents  Int?\n  stripeProductId      String?\n  stripePriceId        String?\n  stripePriceMonthlyId String?\n  stripePriceAnnualId  String?\n  subscriptions        Subscription[]\n}\n\n/**\n * Admin-managed Stripe configuration (singleton row, id = \"singleton\"). Lets a\n * platform admin paste the live secret key + webhook signing secret in the admin\n * console instead of editing values-prod.yaml. Both secrets are encrypted at rest\n * (encryptJson) and write-only (never returned to the browser — only a hasX flag).\n * Per-plan price IDs are NOT secrets and live in Plan.* ; they are edited via the\n * same admin page. Billing reads this DB config FIRST and falls back to env, so an\n * empty row keeps the current env-based behaviour with zero regression.\n */\nmodel StripeConfig {\n  id               String   @id @default(\"singleton\")\n  secretKeyEnc     String?\n  webhookSecretEnc String?\n  updatedByUserId  String?\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n}\n\n/**\n * Admin-managed social-login provider config (2026-06-30): a platform admin can\n * paste each sign-in provider's (GitHub / Google) OAuth client_id + client_secret\n * in /admin/oauth-providers instead of editing the platform Secret + redeploying.\n * One row per provider (provider key is the PK). The secret is stored encrypted\n * (encryptJson) and is write-only. The login flow reads this row DB-first and\n * falls back to the *_CLIENT_ID/*_CLIENT_SECRET env vars, so an absent row keeps\n * the current env-based behaviour with zero regression. `enabled = false`\n * disables the provider's sign-in button without clearing the stored credentials.\n */\nmodel LoginProviderConfig {\n  provider        String   @id // 'github' | 'google'\n  clientId        String?\n  clientSecretEnc String?\n  scopes          String[]\n  enabled         Boolean  @default(true)\n  updatedByUserId String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel UsageEvent {\n  id             String       @id @default(cuid())\n  organizationId String\n  userId         String?\n  type           String\n  quantity       Int          @default(1)\n  metadata       Json?\n  createdAt      DateTime     @default(now())\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, type])\n  // Per-user usage reporting filters by userId over time; was a full-scan.\n  @@index([userId, createdAt])\n}\n\nmodel QuotaLedger {\n  id             String       @id @default(cuid())\n  organizationId String\n  key            String\n  delta          Int\n  reason         String\n  expiresAt      DateTime?\n  createdAt      DateTime     @default(now())\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, key])\n}\n\nmodel QuotaOverride {\n  id              String       @id @default(cuid())\n  organizationId  String\n  key             String\n  limit           Int\n  reason          String\n  createdByUserId String?\n  expiresAt       DateTime?\n  createdAt       DateTime     @default(now())\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, key])\n}\n\nmodel StripeEvent {\n  id             String        @id\n  organizationId String?\n  type           String\n  processedAt    DateTime      @default(now())\n  payload        Json\n  organization   Organization? @relation(fields: [organizationId], references: [id], onDelete: SetNull)\n\n  @@index([organizationId])\n  @@index([type])\n}\n\n/**\n * A Stripe webhook whose side-effect processing threw (E28 admin health).\n * The full event payload is stored so an admin can replay it later — replays\n * re-run the SAME processing path with this stored payload (signature\n * verification is skipped by design: the payload came from our own store, not\n * the network). `resolvedAt` is set when a replay (or Stripe's own retry)\n * succeeds; unresolved rows feed the /admin/stripe \"Failed webhooks\" table.\n */\nmodel StripeWebhookFailure {\n  id         String    @id @default(cuid())\n  eventId    String    @unique\n  type       String\n  payload    Json\n  attempts   Int       @default(1)\n  lastError  String\n  failedAt   DateTime  @default(now())\n  resolvedAt DateTime?\n\n  @@index([resolvedAt, failedAt])\n}\n\nmodel AiConversation {\n  id        String      @id @default(cuid())\n  projectId String?\n  userId    String\n  title     String?\n  createdAt DateTime    @default(now())\n  project   Project?    @relation(fields: [projectId], references: [id], onDelete: SetNull)\n  user      User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messages  AiMessage[]\n\n  @@index([projectId])\n  @@index([userId])\n}\n\nmodel AiMessage {\n  id             String         @id @default(cuid())\n  conversationId String\n  role           String\n  content        String\n  createdAt      DateTime       @default(now())\n  conversation   AiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  toolCalls      AiToolCall[]\n  tokenUsage     AiTokenUsage?\n\n  // listAiMessages runs WHERE conversationId = ? ORDER BY createdAt DESC on the\n  // highest-volume table in the product (one row per chat message) on every\n  // conversation open — without this it was a full table scan + sort.\n  @@index([conversationId, createdAt])\n}\n\nmodel AiToolCall {\n  id        String    @id @default(cuid())\n  messageId String\n  name      String\n  input     Json?\n  output    Json?\n  createdAt DateTime  @default(now())\n  message   AiMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n\n  @@index([messageId])\n}\n\nmodel AiTokenUsage {\n  id                 String    @id @default(cuid())\n  messageId          String    @unique\n  provider           String\n  model              String\n  inputTokens        Int\n  outputTokens       Int\n  estimatedCostCents Int       @default(0)\n  createdAt          DateTime  @default(now())\n  message            AiMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n}\n\n// F18 — per-request AI provider outcome, so the admin Providers panel can show a\n// REAL p95 latency + 24h error rate per provider (previously metricsAvailable:false\n// because no per-request provider metric source existed). Written best-effort on\n// BOTH success and failure from the chat completion path; standalone, no FK to a\n// message (an errored request may never create one). Indexed on (provider, createdAt)\n// for the 24h rolling aggregation. Pruned by the usage-retention cron.\nmodel ProviderRequestMetric {\n  id         String   @id @default(cuid())\n  provider   String\n  model      String?\n  latencyMs  Int\n  errored    Boolean  @default(false)\n  statusCode Int?\n  source     String?\n  createdAt  DateTime @default(now())\n\n  @@index([provider, createdAt])\n  @@index([createdAt])\n}\n\n// 👍/👎 a user left on an assistant chat message (2026-07-03). messageId is\n// the client-side chat message id — standalone chats keep their transcript in\n// browser IndexedDB and never persist an AiMessage row, so this deliberately\n// has no AiMessage FK. One row per (userId, messageId): repeat votes upsert,\n// retracting a vote (toggling the thumb off) deletes the row.\nmodel AiMessageFeedback {\n  id        String   @id @default(cuid())\n  userId    String\n  messageId String\n  chatId    String?\n  vote      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, messageId])\n  @@index([messageId])\n}\n\nmodel AiCostLedger {\n  id             String       @id @default(cuid())\n  organizationId String\n  projectId      String?\n  conversationId String?\n  messageId      String?\n  provider       String\n  model          String\n  inputTokens    Int\n  outputTokens   Int\n  costCents      Int\n  reason         String\n  createdAt      DateTime     @default(now())\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, createdAt])\n  @@index([projectId])\n  @@index([conversationId])\n}\n\nmodel AbuseEvent {\n  id             String        @id @default(cuid())\n  organizationId String?\n  userId         String?\n  type           String\n  severity       String\n  metadata       Json?\n  createdAt      DateTime      @default(now())\n  organization   Organization? @relation(fields: [organizationId], references: [id], onDelete: SetNull)\n\n  // evaluateUsageAbuse queries by (organizationId, type) on the usage hot path.\n  @@index([organizationId, type, createdAt])\n}\n\nmodel SupportTicket {\n  id             String              @id @default(cuid())\n  organizationId String?\n  userId         String?\n  subject        String\n  status         SupportTicketStatus @default(OPEN)\n  metadata       Json?\n  createdAt      DateTime            @default(now())\n  updatedAt      DateTime            @updatedAt\n  organization   Organization?       @relation(fields: [organizationId], references: [id], onDelete: SetNull)\n  user           User?               @relation(fields: [userId], references: [id], onDelete: SetNull)\n  // I25: real conversation thread. Virtual relation (no column on this table);\n  // the FK lives on TicketMessage. Purely additive.\n  messages       TicketMessage[]\n}\n\n// I25: one message in a support ticket's conversation (the user's replies AND\n// admin responses). Additive — no change to SupportTicket's own columns.\nenum TicketMessageAuthor {\n  USER\n  ADMIN\n  SYSTEM\n}\n\nmodel TicketMessage {\n  id           String              @id @default(cuid())\n  ticketId     String\n  authorType   TicketMessageAuthor\n  authorUserId String?\n  body         String\n  createdAt    DateTime            @default(now())\n  ticket       SupportTicket       @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId])\n}\n\nmodel FeatureFlag {\n  id             String        @id @default(cuid())\n  organizationId String?\n  key            String\n  enabled        Boolean       @default(false)\n  rules          Json?\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n  organization   Organization? @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, key])\n}\n\nmodel SystemSetting {\n  id        String   @id @default(cuid())\n  key       String   @unique\n  value     Json\n  updatedAt DateTime @updatedAt\n}\n\nmodel EmailVerificationToken {\n  id        String    @id @default(cuid())\n  userId    String\n  // The email this token was issued to verify. At consume time the user's\n  // CURRENT email must still match, so a token can't verify an address the user\n  // changed away from. Nullable for backward-compat with pre-migration tokens.\n  email     String?\n  tokenHash String    @unique\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\n// One-time-use record of consumed SAML assertion IDs, so a captured assertion\n// can't be replayed within its validity window. Pruned by expiresAt.\nmodel SamlAssertion {\n  id             String   @id @default(cuid())\n  organizationId String\n  assertionId    String\n  expiresAt      DateTime\n  consumedAt     DateTime @default(now())\n\n  @@unique([organizationId, assertionId])\n  @@index([expiresAt])\n}\n\n// Short-lived, single-use credentials for browser -> API runtime WebSocket\n// upgrades. Only a SHA-256 hash is persisted; the raw ticket travels in the\n// Sec-WebSocket-Protocol header, never in the URL. The conditional consume in\n// PrismaApiStore makes replay protection atomic across API replicas.\nmodel RuntimeWebSocketTicket {\n  id                  String    @id @default(cuid())\n  tokenHash           String    @unique\n  userId              String\n  // Exact :workspaceId URL segment. It may be a project-id alias.\n  workspaceId         String\n  // Authoritative scope resolved server-side when the ticket is minted.\n  projectId           String\n  resolvedWorkspaceId String\n  endpoint            String\n  expiresAt           DateTime\n  consumedAt          DateTime?\n  createdAt           DateTime  @default(now())\n  user                User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  project             Project   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([projectId])\n  @@index([resolvedWorkspaceId])\n  @@index([expiresAt])\n}\n\nmodel PasswordResetToken {\n  id        String    @id @default(cuid())\n  userId    String\n  tokenHash String    @unique\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel MfaRecoveryCode {\n  id        String    @id @default(cuid())\n  userId    String\n  codeHash  String\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, codeHash])\n  @@index([userId])\n}\n\nmodel EnterpriseOrganizationSettings {\n  organizationId         String       @id\n  ipAllowlist            String[]\n  sessionDurationMinutes Int          @default(43200)\n  requireMfaForAdmins    Boolean      @default(true)\n  dataRetentionDays      Int          @default(365)\n  legalHoldEnabled       Boolean      @default(false)\n  ssoEnforced            Boolean      @default(false)\n  ssoEnforcedAt          DateTime?\n  updatedAt              DateTime     @updatedAt\n  organization           Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n}\n\nmodel VerifiedDomain {\n  id                String       @id @default(cuid())\n  organizationId    String\n  domain            String\n  verificationToken String\n  verifiedAt        DateTime?\n  redirectWww       Boolean      @default(true)\n  wildcardEnabled   Boolean      @default(false)\n  sslStatus         String       @default(\"pending_dns\")\n  createdAt         DateTime     @default(now())\n  organization      Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, domain])\n  @@index([domain])\n}\n\nmodel SsoConfiguration {\n  id              String       @id @default(cuid())\n  organizationId  String\n  type            String\n  enabled         Boolean      @default(true)\n  encryptedConfig String\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, type])\n}\n\nmodel ScimToken {\n  id                String       @id @default(cuid())\n  organizationId    String\n  name              String\n  tokenHash         String       @unique\n  lastUsedAt        DateTime?\n  createdAt         DateTime     @default(now())\n  // F16 — 24h dual-valid rotation: on rotate the old hash moves to\n  // previousTokenHash and rotatedAt is stamped; the previous token keeps\n  // authenticating until rotatedAt + 24h so an IdP can roll over with no downtime.\n  previousTokenHash String?\n  rotatedAt         DateTime?\n  organization      Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId])\n  @@index([previousTokenHash])\n}\n\nmodel CustomRole {\n  id             String       @id @default(cuid())\n  organizationId String\n  key            String\n  name           String\n  permissions    String[]\n  createdAt      DateTime     @default(now())\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, key])\n}\n\nmodel SiemWebhook {\n  id               String       @id @default(cuid())\n  organizationId   String\n  url              String\n  secretHash       String\n  secretCiphertext String\n  enabled          Boolean      @default(true)\n  lastDeliveredAt  DateTime?\n  // Secondary keyset cursor paired with lastDeliveredAt so same-millisecond\n  // audit rows beyond a batch boundary are not silently skipped on delivery.\n  lastDeliveredId  String?\n  createdAt        DateTime     @default(now())\n  organization     Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId])\n  @@index([organizationId, lastDeliveredAt])\n}\n\nmodel ApiKey {\n  id             String        @id @default(cuid())\n  organizationId String?\n  userId         String?\n  name           String\n  keyHash        String        @unique\n  keyPrefix      String?\n  scopes         String[]\n  lastUsedAt     DateTime?\n  expiresAt      DateTime?\n  createdAt      DateTime      @default(now())\n  organization   Organization? @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  user           User?         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([organizationId])\n}\n\nmodel OAuthConnection {\n  id          String   @id @default(cuid())\n  userId      String\n  provider    String\n  externalId  String\n  accessHash  String\n  refreshHash String?\n  createdAt   DateTime @default(now())\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, externalId])\n  @@index([userId])\n}\n\nenum McpDomain {\n  AI_AGENTS\n  CODE_EXECUTION\n  DATABASES\n  DEVOPS\n  DEVELOPER_TOOLS\n  COMMUNICATION\n  PRODUCTIVITY\n  KNOWLEDGE\n  WEB_BROWSING\n  SEARCH\n  CLOUD\n  SECURITY\n  FILESYSTEM\n  VERSION_CONTROL\n  MONITORING\n  OTHER\n}\n\nenum McpTransport {\n  STDIO\n  SSE\n  STREAMABLE_HTTP\n}\n\nmodel McpCatalogEntry {\n  id                  String       @id @default(cuid())\n  slug                String       @unique\n  name                String\n  nameFr              String?\n  description         String\n  descriptionFr       String?\n  domain              McpDomain\n  tags                String[]\n  tagsFr              String[]     @default([])\n  author              String\n  homepageUrl         String?\n  iconUrl             String?\n  version             String\n  transport           McpTransport\n  configTemplate      Json\n  configSchema        Json         @default(\"{}\")\n  configSchemaFr      Json         @default(\"{}\")\n  installCount        Int          @default(0)\n  featured            Boolean      @default(false)\n  verified            Boolean      @default(false)\n  featuredForIdePanel Boolean      @default(false)\n  // Global admin kill-switch. false = hidden from the catalog, new installs\n  // blocked, and existing installs soft-disabled (reversible on re-enable —\n  // nothing is deleted). Defaults true so every existing row stays available.\n  enabled             Boolean      @default(true)\n  publishedAt         DateTime     @default(now())\n  updatedAt           DateTime     @updatedAt\n  installs            McpInstall[]\n\n  @@index([domain])\n  @@index([featured, verified])\n  @@index([featuredForIdePanel])\n  @@index([enabled])\n}\n\nmodel McpInstall {\n  id             String          @id @default(cuid())\n  catalogEntryId String\n  userId         String\n  organizationId String?\n  alias          String\n  configJson     Json\n  enabled        Boolean         @default(true)\n  installedAt    DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n  catalogEntry   McpCatalogEntry @relation(fields: [catalogEntryId], references: [id], onDelete: Cascade)\n  user           User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  organization   Organization?   @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, alias])\n  @@index([organizationId])\n  @@index([catalogEntryId])\n}\n\n// Server-side persistence for the MCP \"Configuration\" tab (manually authored\n// `{ mcpServers: { … } }` JSON + the max sequential-LLM-step count). Replaces\n// the previous localStorage-only storage (audit H5) so the chat/agent runtime\n// can read a user's manually-configured servers — alongside their marketplace\n// installs — when assembling the live MCP tool set. One row per user.\nmodel McpUserConfig {\n  id          String   @id @default(cuid())\n  userId      String   @unique\n  configJson  Json     @default(\"{}\")\n  maxLLMSteps Int      @default(5)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Platform-wide (global) MCP policy — one tier ABOVE the per-org policy that\n// reuses OrganizationConnectorPolicy. One row per catalog slug; `mode` is\n// 'forced' | 'allowed' | 'blocked' (validated in the app, mirroring the org\n// policy modes). Install resolution evaluates GLOBAL first, then the org\n// policy. Absence of any row = default-open, so this is additive and inert\n// until an admin sets a policy.\nmodel McpGlobalPolicy {\n  id        String   @id @default(cuid())\n  slug      String   @unique\n  mode      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([mode])\n}\n\n// Server-side store for a shared conversation snapshot. Replaces embedding the\n// full conversation in the share URL: a share mints a random, HMAC-signed\n// token (stored here only as a hash) that the /share view redeems to fetch the\n// snapshot. Standalone (no FK) so a share can outlive its project/author.\nmodel ChatShare {\n  id             String    @id @default(cuid())\n  tokenHash      String    @unique\n  conversationId String\n  projectId      String\n  authorUserId   String\n  title          String?\n  payloadJson    Json\n  allowFork      Boolean   @default(false)\n  expiresAt      DateTime?\n  revokedAt      DateTime?\n  createdAt      DateTime  @default(now())\n\n  @@index([projectId])\n  @@index([authorUserId])\n}\n\nenum AgentRunStatus {\n  PENDING\n  RUNNING\n  COMPLETE\n  PARTIAL\n  FAILED\n}\n\nenum AgentRunResultStatus {\n  COMPLETE\n  PARTIAL\n  FAILED\n}\n\nmodel AgentRun {\n  id             String           @id @default(cuid())\n  organizationId String?\n  userId         String?\n  conversationId String?\n  projectId      String?\n  mode           String\n  status         AgentRunStatus   @default(PENDING)\n  reason         String?\n  rolesPlanned   Json\n  startedAt      DateTime         @default(now())\n  completedAt    DateTime?\n  metadata       Json             @default(\"{}\")\n  results        AgentRunResult[]\n  consensus      ConsensusRecord?\n  user           User?            @relation(fields: [userId], references: [id], onDelete: SetNull)\n  organization   Organization?    @relation(fields: [organizationId], references: [id], onDelete: SetNull)\n\n  @@index([organizationId, startedAt])\n  @@index([userId, startedAt])\n  @@index([conversationId])\n}\n\nmodel AgentRunResult {\n  id           String               @id @default(cuid())\n  runId        String\n  roleId       String\n  status       AgentRunResultStatus\n  summary      String\n  files        Json                 @default(\"[]\")\n  risks        Json                 @default(\"[]\")\n  verification Json                 @default(\"[]\")\n  rawOutput    String?\n  errorMessage String?\n  startedAt    DateTime             @default(now())\n  completedAt  DateTime?\n  run          AgentRun             @relation(fields: [runId], references: [id], onDelete: Cascade)\n\n  @@unique([runId, roleId])\n  @@index([runId])\n}\n\nenum ConsensusAlgorithm {\n  QUORUM\n  BYZANTINE_PBFT\n  WEIGHTED_PLURALITY\n}\n\nenum ConsensusOutcome {\n  ACCEPTED\n  REJECTED\n  PARTIAL\n  ABSTAINED\n}\n\nmodel ConsensusRecord {\n  id             String             @id @default(cuid())\n  runId          String             @unique\n  algorithm      ConsensusAlgorithm\n  threshold      Float\n  outcome        ConsensusOutcome\n  agreementScore Float\n  claimVotes     Json\n  conflicts      Json               @default(\"[]\")\n  consolidated   Json\n  rounds         Int                @default(1)\n  durationMs     Int\n  createdAt      DateTime           @default(now())\n  run            AgentRun           @relation(fields: [runId], references: [id], onDelete: Cascade)\n}\n\n/// Runtime/K8s orchestration state owned by services/workspace-manager.\n/// Distinct from the user-facing Workspace model (which carries projectId\n/// and runtimeMode for the IDE): this row tracks the actual pod, PVC,\n/// service and agent-token-secret names allocated to the workspace, plus\n/// the lifecycle status and the last-active timestamp used by the GC sweep.\n/// The id matches the workspaceId used by services/api and the K8s object\n/// names (\"workspace-${id}\", \"pvc-${id}\", \"agent-token-${id}\"), so this row\n/// is effectively the canonical state shared between workspace-manager\n/// replicas — replacing the file-backed JsonWorkspaceStore.\nmodel WorkspaceRuntime {\n  id                   String     @id\n  orgId                String\n  projectId            String\n  plan                 Json\n  status               String\n  pvcName              String\n  podName              String\n  serviceName          String\n  agentTokenSecretName String\n  error                String?\n  createdAt            DateTime   @default(now())\n  lastActiveAt         DateTime   @default(now())\n  // Last time this runtime's active compute was metered to the billing usage\n  // ledger (P4 metering emitter). The GC meters the window from here (or\n  // createdAt) to lastActiveAt on stop, then advances this marker — idempotent\n  // across manager restarts. Null until first metered.\n  lastMeteredAt        DateTime?\n  /// Durable account-purge barrier. A runtime can be (re)provisioned only when\n  /// this flag is false. The plan id + per-attempt token fence every release.\n  purgeFrozen          Boolean    @default(false)\n  purgePlanId          String?\n  purgeFenceToken      String?\n  purgeFrozenAt        DateTime?\n  updatedAt            DateTime   @updatedAt\n  purgePlan            PurgePlan? @relation(fields: [purgePlanId], references: [id], onDelete: SetNull)\n\n  @@index([orgId])\n  @@index([projectId])\n  @@index([status, lastActiveAt])\n  @@index([purgePlanId, purgeFrozen])\n}\n\n// --- Integrations panel: connector catalog, user-scoped connections,\n// per-project links, enterprise overrides, reconnection alerts,\n// integration feature requests. See docs/INTEGRATIONS_MASTER_PLAN.md.\n\nmodel ConnectorCatalog {\n  id          String @id @default(cuid())\n  provider    String @unique\n  displayName String\n  description String\n  category    String\n  authType    String\n  section     String\n  logoUrl     String\n\n  defaultClientId        String?\n  defaultClientSecretEnc String?\n  authorizeUrl           String?\n  tokenUrl               String?\n  revokeUrl              String?\n  userInfoUrl            String?\n  defaultScopes          String[]\n  availableScopes        String[]\n\n  apiKeyFields       Json?\n  apiKeyTestEndpoint String?\n\n  triggersSupported   String[]\n  triggerDescriptions Json     @default(\"{}\")\n\n  webhookSupport          Boolean @default(false)\n  webhookSignatureScheme  String?\n  webhookSigningSecretEnc String?\n\n  minPlanTier         String  @default(\"free\")\n  forAgentUse         Boolean @default(true)\n  displayOrder        Int     @default(0)\n  featuredForIdePanel Boolean @default(false)\n  enabled             Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([section, enabled])\n  @@index([category])\n}\n\nmodel UserConnection {\n  id                   String @id @default(cuid())\n  userId               String\n  provider             String\n  externalAccountId    String\n  externalAccountLabel String\n\n  accessTokenEncrypted  String?\n  refreshTokenEncrypted String?\n  apiKeyFieldsEncrypted Json?\n\n  scopes            String[]\n  tokenExpiresAt    DateTime?\n  status            String    @default(\"active\")\n  lastUsedAt        DateTime?\n  // Cursor for the background token health-check sweep, kept separate from the\n  // user-facing lastUsedAt so the sweep no longer clobbers \"last used\".\n  lastHealthCheckAt DateTime?\n  forAgentUse       Boolean   @default(true)\n\n  oauthAppSource     String  @default(\"e_code_default\")\n  oauthAppOverrideId String?\n\n  createdByUserId String\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  revokedAt       DateTime?\n\n  user               User                          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  oauthAppOverride   OrganizationOAuthAppOverride? @relation(fields: [oauthAppOverrideId], references: [id])\n  projectLinks       ProjectConnectionLink[]\n  reconnectionAlerts ReconnectionAlert[]\n\n  @@unique([userId, provider, externalAccountId])\n  @@index([userId, provider])\n  @@index([status])\n  // Background token-health sweep cursors on lastHealthCheckAt; was a full-scan.\n  @@index([lastHealthCheckAt])\n}\n\nmodel ProjectConnectionLink {\n  id               String    @id @default(cuid())\n  projectId        String\n  userConnectionId String\n  linkedByUserId   String\n  linkedAt         DateTime  @default(now())\n  unlinkedAt       DateTime?\n\n  project        Project        @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  userConnection UserConnection @relation(fields: [userConnectionId], references: [id], onDelete: Cascade)\n  linkedByUser   User           @relation(\"LinkedByUser\", fields: [linkedByUserId], references: [id])\n\n  @@unique([projectId, userConnectionId])\n  @@index([projectId])\n  @@index([userConnectionId])\n  // \"who linked this\" lookups + future user-offboarding scans; was a full-scan.\n  @@index([linkedByUserId])\n}\n\nmodel OrganizationOAuthAppOverride {\n  id                    String    @id @default(cuid())\n  organizationId        String\n  provider              String\n  clientId              String\n  clientSecretEncrypted String\n  scopes                String[]\n  configuredByUserId    String\n  testedAt              DateTime?\n  testStatus            String?\n  testError             String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  organization     Organization     @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  configuredByUser User             @relation(\"ConfiguredByUser\", fields: [configuredByUserId], references: [id])\n  userConnections  UserConnection[]\n\n  @@unique([organizationId, provider])\n}\n\nmodel OrganizationConnectorPolicy {\n  id                String   @id @default(cuid())\n  organizationId    String\n  provider          String\n  enabled           Boolean  @default(true)\n  allowedRoleKeys   String[]\n  rateLimitOverride Int?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, provider])\n}\n\nmodel ReconnectionAlert {\n  id               String    @id @default(cuid())\n  userConnectionId String\n  reason           String\n  detectedAt       DateTime  @default(now())\n  resolvedAt       DateTime?\n  notifiedAt       DateTime?\n\n  userConnection UserConnection @relation(fields: [userConnectionId], references: [id], onDelete: Cascade)\n\n  @@index([userConnectionId, resolvedAt])\n}\n\n/// Per-user in-app notification feed (2026-07-02). A durable, user-scoped\n/// inbox surfaced in the SaaS account area: producers write a row, the user\n/// lists unread + recent and marks items read. Distinct from ReconnectionAlert\n/// (a connector-domain resolve queue) — this is the general feed. The first\n/// real producer is the connector reconnection alert: when one is raised the\n/// API also drops a Notification so the feed is non-empty in reality.\nmodel Notification {\n  id            String    @id @default(cuid())\n  userId        String\n  /// Coarse routing/tone bucket, aligned with the preferences surfaces:\n  /// \"security\" | \"billing\" | \"deployments\" | \"team\" | \"system\".\n  category      String    @default(\"system\")\n  title         String\n  body          String?\n  /// Stable i18n descriptor for newly-produced notifications. Nullable keeps\n  /// every historical row and older producer compatible with title/body.\n  messageKey    String?\n  messageParams Json?\n  /// Optional in-app link the notification points at (e.g. /account/connections).\n  linkUrl       String?\n  /// Free-form producer metadata (e.g. the source alert id / provider) so the\n  /// feed can be traced back to its origin without extra columns.\n  metadata      Json?\n  readAt        DateTime?\n  createdAt     DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Feed query is \"this user's rows, unread first / newest first\"; the partial\n  // shape is covered well enough by the composite index below.\n  @@index([userId, readAt, createdAt])\n}\n\nmodel NewsletterSubscriber {\n  id             String    @id @default(cuid())\n  /// Normalized (lowercased, trimmed) address; unique so re-subscribing is an\n  /// idempotent upsert rather than a duplicate row.\n  email          String    @unique\n  /// Where the subscription came from (\"footer\", \"newsletter-page\", ...).\n  source         String    @default(\"footer\")\n  createdAt      DateTime  @default(now())\n  confirmedAt    DateTime?\n  unsubscribedAt DateTime?\n}\n\n/// Sales-contact leads submitted through the public /contact-sales form.\n/// The row id doubles as the reference number quoted back to the prospect\n/// (first 8 chars, uppercased), so sales can locate the lead from the\n/// reference alone.\nmodel ContactRequest {\n  id        String   @id @default(cuid())\n  email     String\n  name      String?\n  company   String\n  teamSize  String?\n  message   String\n  /// Marketing page the form was submitted from (\"/contact-sales\", ...).\n  pagePath  String?\n  createdAt DateTime @default(now())\n}\n\nmodel IntegrationFeatureRequest {\n  id                 String   @id @default(cuid())\n  userId             String\n  organizationId     String?\n  integrationName    String\n  useCaseDescription String\n  status             String   @default(\"pending\")\n  createdAt          DateTime @default(now())\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  organization Organization? @relation(fields: [organizationId], references: [id], onDelete: SetNull)\n\n  @@index([status])\n  @@index([userId])\n}\n\n/// Delivery / bounce / complaint notifications received from transactional\n/// email providers. The recipient is stored verbatim (not joined to User) so\n/// we can keep history for addresses that don't have an account — password\n/// reset and email-verification flows fire before the user exists.\nmodel EmailDeliveryEvent {\n  id              String   @id @default(cuid())\n  provider        String\n  providerEventId String\n  type            String\n  email           String\n  emailMessageId  String?\n  subject         String?\n  fromAddress     String?\n  payload         Json\n  receivedAt      DateTime @default(now())\n\n  @@unique([provider, providerEventId])\n  @@index([email])\n  @@index([type])\n  @@index([emailMessageId])\n}\n\n// ===========================================================================\n// Replit-parity billing: credit wallet, effort-based checkpoints, and the\n// admin-owned provider/model registry. All additive and dormant until the\n// `BILLING_CREDITS_ENABLED` / `MODEL_REGISTRY_DB` flags are turned on, so the\n// existing flat-rate Stripe billing path is unaffected. See\n// docs/REPLIT_PARITY_SPEC.md.\n// ===========================================================================\n\n/// One USD-cent credit balance per organization. `balanceCents` is a\n/// materialized cache of the sum of `CreditLedger.deltaCents`; the ledger is\n/// the source of truth. `budgetCapCents` null = pay-as-you-go disabled.\nmodel CreditWallet {\n  id                        String         @id @default(cuid())\n  organizationId            String         @unique\n  balanceCents              Int            @default(0)\n  currency                  String         @default(\"usd\")\n  // Replit \"Usage Limit\": cap on usage-based spend past included credits.\n  budgetCapCents            Int?\n  // Replit \"Service Shutdown Limit\": suspend usage-based services when reached.\n  serviceShutdownCents      Int?\n  autoTopupCents            Int?\n  // Replit usage-based spend alerts (50/80/100%). De-dup marker: the highest\n  // alert rung sent in the current billing period, and that period's start, so\n  // each rung fires once and the ladder resets every period. Dormant until\n  // BILLING_CREDITS_ENABLED. See spend-alerts.ts.\n  lastSpendAlertPct         Int?\n  lastSpendAlertPeriodStart DateTime?\n  createdAt                 DateTime       @default(now())\n  updatedAt                 DateTime       @updatedAt\n  organization              Organization   @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  entries                   CreditLedger[]\n}\n\n/// Purchased credit pack (Replit). Credits expire 6 months after purchase, are\n/// consumed earliest-expiring-first, and do NOT roll over after expiry.\n/// `remainingCents` is decremented as the pack is drawn down.\nmodel CreditPack {\n  id                    String       @id @default(cuid())\n  organizationId        String\n  purchasedCents        Int\n  remainingCents        Int\n  expiresAt             DateTime\n  stripePaymentIntentId String?\n  createdAt             DateTime     @default(now())\n  organization          Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, expiresAt])\n}\n\nenum CreditEntryKind {\n  GRANT\n  CONSUMPTION\n  PAYG_CHARGE\n  REFUND\n  ADJUSTMENT\n  EXPIRY\n}\n\n/// Append-only credit movements. Positive deltas are grants/refunds, negative\n/// are consumption/charges. `checkpointId` links a CONSUMPTION to the agent\n/// request that produced it. `expiresAt` supports daily/monthly grants that do\n/// not roll over (Starter plan).\nmodel CreditLedger {\n  id             String          @id @default(cuid())\n  walletId       String\n  organizationId String\n  deltaCents     Int\n  kind           CreditEntryKind\n  reason         String\n  checkpointId   String?\n  expiresAt      DateTime?\n  metadata       Json?\n  createdAt      DateTime        @default(now())\n  wallet         CreditWallet    @relation(fields: [walletId], references: [id], onDelete: Cascade)\n  organization   Organization    @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  // NOTE: a PARTIAL UNIQUE index \"CreditLedger_org_checkpoint_payg_key\" on\n  // (organizationId, checkpointId) WHERE kind='PAYG_CHARGE' is defined in raw SQL\n  // (migration 0045) — Prisma's schema can't express a WHERE-filtered unique index.\n  // It backs recordPaygCharge's atomic create+catch-P2002 dedup. Do not drop it.\n\n  @@index([organizationId, createdAt])\n  @@index([walletId, createdAt])\n  @@index([checkpointId])\n  @@index([kind, expiresAt])\n  // Org-scoped credit-expiry sweep filters organizationId + kind + expiresAt\n  // together; the kind/expiresAt-only index wasn't org-scoped.\n  @@index([organizationId, kind, expiresAt])\n}\n\nenum CheckpointStatus {\n  PENDING\n  COMPLETED\n  FAILED\n}\n\n/// Effort-based checkpoint: exactly one per agent request. Bundles the real\n/// effort (tokens + wall-time + attributed compute) into a single user-visible\n/// credit charge (proof-of-work). `creditCents` is always >= the real provider\n/// cost (`rawProviderCents`) by the configured margin.\nmodel AgentCheckpoint {\n  id               String           @id @default(cuid())\n  organizationId   String\n  userId           String?\n  projectId        String?\n  conversationId   String?\n  runId            String?\n  status           CheckpointStatus @default(PENDING)\n  highPowerModel   Boolean          @default(false)\n  extendedThinking Boolean          @default(false)\n  // Replit Agent build tier (lite | economy | power) and Turbo mode (Pro:\n  // ~2.5x faster, up to ~6x cost). Both feed the effort-based estimate.\n  buildTier        String           @default(\"power\")\n  turboMode        Boolean          @default(false)\n  inputTokens      Int              @default(0)\n  outputTokens     Int              @default(0)\n  wallMs           Int              @default(0)\n  computeCents     Int              @default(0)\n  rawProviderCents Int              @default(0)\n  creditCents      Int              @default(0)\n  startedAt        DateTime         @default(now())\n  completedAt      DateTime?\n  organization     Organization     @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, startedAt])\n  @@index([projectId])\n  @@index([runId])\n}\n\n/// Replit-parity per-user spend limit (Enterprise). An admin can cap an\n/// individual member's usage-based spend below the org/workspace default; the\n/// per-member override takes precedence over the org budget cap.\nmodel UserSpendLimit {\n  id             String       @id @default(cuid())\n  organizationId String\n  userId         String\n  limitCents     Int\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, userId])\n  @@index([organizationId])\n}\n\n/// Admin-owned AI provider registry. `apiKeySecret` is the *name* of a secret\n/// in the platform secret manager — never the key material itself.\nmodel ProviderConfig {\n  id           String        @id @default(cuid())\n  provider     String        @unique\n  displayName  String\n  enabled      Boolean       @default(false)\n  apiKeySecret String?\n  /// Admin-set platform API key for this provider, encrypted with encryptJson\n  /// (write-only, never returned). Distinct from `apiKeySecret`, which holds only\n  /// the NAME of a secret. Runtime resolves DB-first → *_API_KEY env fallback.\n  apiKeyEnc    String?\n  baseUrl      String?\n  byokAllowed  Boolean       @default(false)\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n  models       ModelConfig[]\n}\n\n/// Admin-owned model registry. Users may only see/use models with\n/// `enabled = true` whose `enabledPlans` include their plan. Pricing here drives\n/// effort-based credit cost.\nmodel ModelConfig {\n  id               String         @id @default(cuid())\n  providerConfigId String\n  modelId          String\n  displayName      String\n  enabled          Boolean        @default(false)\n  enabledPlans     Json\n  isHighPower      Boolean        @default(false)\n  supportsThinking Boolean        @default(false)\n  inputCentsPerM   Int\n  outputCentsPerM  Int\n  contextWindow    Int\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n  providerConfig   ProviderConfig @relation(fields: [providerConfigId], references: [id], onDelete: Cascade)\n\n  @@unique([providerConfigId, modelId])\n  @@index([enabled])\n}\n\nenum DatabaseInstanceStatus {\n  PROVISIONING\n  ACTIVE\n  SUSPENDED\n  FAILED\n  DELETED\n}\n\n/// Managed Postgres database for a project (Replit \"Database\" tab). Phase-1\n/// scaffold for point-in-time rollback: the row models the instance and its\n/// retention window; provisioning + WAL-based PITR are wired in later phases and\n/// gated behind DB_ROLLBACK_ENABLED, so this table is dormant until then.\n/// `retentionDays` is the plan-derived PITR window (Pro = 28).\nmodel DatabaseInstance {\n  id                     String                 @id @default(cuid())\n  projectId              String\n  organizationId         String\n  // P2d dev/prod split: a project has a `development` instance (its workspace\n  // DB) and, once published, a separate `production` instance. Existing rows\n  // backfill to 'development', preserving the prior one-per-project behaviour.\n  environment            String                 @default(\"development\")\n  status                 DatabaseInstanceStatus @default(PROVISIONING)\n  engine                 String                 @default(\"postgres\")\n  region                 String?\n  sizeBytes              BigInt                 @default(0)\n  retentionDays          Int                    @default(7)\n  pitrEnabled            Boolean                @default(false)\n  // Durable provisioning lifecycle. A request is never allowed to remain\n  // PROVISIONING past this deadline; FAILED keeps a stable, non-secret reason\n  // and can be atomically claimed for a retry.\n  provisioningDeadlineAt DateTime?\n  lastErrorCode          String?\n  lastErrorAt            DateTime?\n  createdAt              DateTime               @default(now())\n  updatedAt              DateTime               @updatedAt\n  project                Project                @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  snapshots              DatabaseSnapshot[]\n  restores               DatabaseRestore[]\n  remixJobsAsTarget      RemixJob[]             @relation(\"RemixJobTargetDatabase\")\n\n  @@unique([projectId, environment])\n  @@index([organizationId])\n  @@index([status])\n  @@index([status, provisioningDeadlineAt])\n}\n\n/// A recovery point for a DatabaseInstance — either a scheduled automatic\n/// snapshot or a user-requested manual one. `lsn` records the Postgres WAL\n/// position so a restore can target an exact point in time; `expiresAt` is the\n/// retention horizon (older snapshots are pruned). Dormant until PITR ships.\nmodel DatabaseSnapshot {\n  id                 String           @id @default(cuid())\n  databaseInstanceId String\n  kind               String           @default(\"auto\")\n  label              String?\n  lsn                String?\n  sizeBytes          BigInt           @default(0)\n  storageKey         String?\n  createdByUserId    String?\n  createdAt          DateTime         @default(now())\n  expiresAt          DateTime?\n  databaseInstance   DatabaseInstance @relation(fields: [databaseInstanceId], references: [id], onDelete: Cascade)\n\n  @@index([databaseInstanceId, createdAt])\n  @@index([expiresAt])\n}\n\nenum DatabaseRestoreStatus {\n  PENDING\n  RUNNING\n  COMPLETED\n  FAILED\n}\n\n/// A point-in-time restore request for a DatabaseInstance. Targets either a\n/// specific snapshot or an arbitrary `targetTimestamp` within the retention\n/// window (true PITR). Status moves PENDING → RUNNING → COMPLETED/FAILED. The\n/// restore executor is a later phase; rows can be created dormant for the UI.\nmodel DatabaseRestore {\n  id                 String                @id @default(cuid())\n  databaseInstanceId String\n  snapshotId         String?\n  targetTimestamp    DateTime?\n  status             DatabaseRestoreStatus @default(PENDING)\n  requestedByUserId  String?\n  error              String?\n  createdAt          DateTime              @default(now())\n  startedAt          DateTime?\n  completedAt        DateTime?\n  databaseInstance   DatabaseInstance      @relation(fields: [databaseInstanceId], references: [id], onDelete: Cascade)\n\n  @@index([databaseInstanceId, createdAt])\n  @@index([status])\n  // \"restores requested by user\" lookups; was a full-scan (no FK on this column).\n  @@index([requestedByUserId])\n}\n\n/// Fenced, resumable schema migration executed before a production publish.\n/// The SQL itself stays in project storage; only the immutable name/hash plan is\n/// persisted so recovery can reconcile the target without retaining user SQL.\nmodel DBMigrationExecution {\n  id                       String    @id @default(cuid())\n  projectId                String\n  organizationId           String\n  environment              String\n  state                    String    @default(\"LOCK_ACQUIRED\")\n  idempotencyKey           String\n  requestHash              String\n  activeLock               String?   @unique\n  ownerToken               String?\n  version                  Int       @default(0)\n  leaseExpiresAt           DateTime?\n  attempt                  Int       @default(1)\n  plan                     Json\n  statementsSha256         String\n  statementCount           Int       @default(0)\n  appliedStatements        Int       @default(0)\n  backwardCompatible       Boolean\n  forwardCompatible        Boolean\n  backupId                 String?\n  backupVerifiedAt         DateTime?\n  backupVerificationMethod String?\n  deploymentId             String?\n  createdByUserId          String?\n  errorCode                String?\n  startedAt                DateTime  @default(now())\n  completedAt              DateTime?\n  createdAt                DateTime  @default(now())\n  updatedAt                DateTime  @updatedAt\n\n  @@unique([projectId, idempotencyKey])\n  @@index([projectId, environment, state])\n  @@index([activeLock, leaseExpiresAt])\n}\n\n// ---------------------------------------------------------------------------\n// Scheduled tasks (cron). Backs BOTH the Workflows panel schedules AND the\n// Replit-parity \"Scheduled\" deployment type: a command that runs on a cron,\n// exits, and is billed for its RUN TIME (duration x machine size) rather than\n// 24/7. Before this, cron expressions were validated and a nextRunAt was\n// computed, but nothing ever fired them — the feature was dead.\n// ---------------------------------------------------------------------------\n\nenum ScheduledTaskKind {\n  /// Runs an existing Workflows-panel workflow (its ordered steps).\n  WORKFLOW\n  /// Replit \"Scheduled Deployment\": one shell command, on a cron.\n  DEPLOYMENT\n}\n\nenum ScheduledTaskRunStatus {\n  RUNNING\n  SUCCESS\n  FAILED\n  TIMED_OUT\n  /// The previous run was still RUNNING when this tick fired (concurrencyPolicy=FORBID).\n  SKIPPED\n  CANCELED\n}\n\n/// One cron-scheduled unit of work owned by a project. `nextRunAt` is the claim\n/// token: the scheduler advances it inside a conditional UPDATE, so exactly one\n/// api replica can ever own a given tick (no distributed lock needed).\nmodel ScheduledTask {\n  id              String             @id @default(cuid())\n  organizationId  String\n  projectId       String\n  kind            ScheduledTaskKind  @default(DEPLOYMENT)\n  name            String\n  /// Shell command for DEPLOYMENT tasks (run as `sh -lc <command>` in the project sandbox).\n  command         String             @default(\"\")\n  /// For WORKFLOW tasks: the workflow id inside VIBECORE_WORKFLOWS_STATE.\n  workflowId      Int?\n  /// 5-field cron expression, already normalized.\n  cron            String\n  /// IANA timezone the cron fields are interpreted in.\n  timezone        String             @default(\"UTC\")\n  /// Machine size key. The size catalogue itself is owned elsewhere; this is the field only.\n  machineSize     String             @default(\"shared-0.5\")\n  enabled         Boolean            @default(true)\n  /// Hard kill after this many seconds.\n  timeoutSeconds  Int                @default(900)\n  /// FORBID (skip if the previous run is still going) | ALLOW.\n  concurrency     String             @default(\"FORBID\")\n  /// Replit parity: a failed scheduled run is NOT retried by default.\n  maxRetries      Int                @default(0)\n  notifyOnFailure Boolean            @default(true)\n  lastRunAt       DateTime?\n  lastStatus      String?\n  /// Next fire time (UTC). NULL when disabled.\n  nextRunAt       DateTime?\n  createdByUserId String?\n  createdAt       DateTime           @default(now())\n  updatedAt       DateTime           @updatedAt\n  runs            ScheduledTaskRun[]\n\n  @@unique([projectId, kind, workflowId])\n  /// The scheduler's hot query: enabled tasks whose nextRunAt is due.\n  @@index([enabled, nextRunAt])\n  @@index([projectId])\n  @@index([organizationId])\n}\n\n/// One execution. Holds the FULL captured stdout+stderr, the real exit code, the\n/// real duration, and the billing outcome for that duration.\nmodel ScheduledTaskRun {\n  id             String                 @id @default(cuid())\n  taskId         String\n  organizationId String\n  projectId      String\n  status         ScheduledTaskRunStatus @default(RUNNING)\n  /// \"schedule\" | \"manual\"\n  trigger        String                 @default(\"schedule\")\n  attempt        Int                    @default(1)\n  /// The cron instant this run is for (may differ from startedAt under load).\n  scheduledFor   DateTime\n  startedAt      DateTime               @default(now())\n  finishedAt     DateTime?\n  durationMs     Int?\n  exitCode       Int?\n  /// Full captured output (stdout + stderr), not a tail.\n  logs           String                 @default(\"\")\n  error          String?\n  machineSize    String?\n  /// Billed compute units for this run (duration x size). NULL until metered.\n  computeUnits   Float?\n  costCents      Float?\n  meteredAt      DateTime?\n  task           ScheduledTask          @relation(fields: [taskId], references: [id], onDelete: Cascade)\n\n  @@index([taskId, startedAt])\n  @@index([projectId, startedAt])\n  @@index([status])\n}\n\n/// Versioned Agent Routing Card: maps agent modes (Lite/Economy/Power) and\n/// switches (High effort/Turbo) + the harness classifier to concrete provider\n/// models with cost-of-revenue and user pricing. `data` is the serialized\n/// AgentRoutingCard document (packages/billing agent-routing.ts). A config\n/// change inserts a NEW version and closes the previous one (effectiveTo) —\n/// never a deployment, never a mutation of history.\nmodel AgentRoutingCard {\n  id              String    @id @default(cuid())\n  version         Int       @unique\n  active          Boolean   @default(false)\n  data            Json\n  effectiveFrom   DateTime  @default(now())\n  effectiveTo     DateTime?\n  /// Date the cost-of-revenue figures were sourced from provider pricing.\n  sourceDate      String?\n  createdByUserId String?\n  createdAt       DateTime  @default(now())\n  createdBy       User?     @relation(\"AgentRoutingCardAuthor\", fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  @@index([active])\n}\n\n/// One row per routed agent LLM call (admin-only, never shown to the client):\n/// who called, which mode/switches, whether high-effort escalated, the REAL\n/// provider+model used, tokens, cost-of-revenue, credits billed and margin.\n/// Cents are stored as millicents (Int) to keep fractional cost exact.\nmodel AgentCallLog {\n  id                 String   @id @default(cuid())\n  createdAt          DateTime @default(now())\n  userId             String?\n  organizationId     String?\n  projectId          String?\n  /// lite | economy | power\n  mode               String\n  highEffort         Boolean  @default(false)\n  /// true when high-effort actually escalated this call to the escalation line\n  escalated          Boolean  @default(false)\n  turbo              Boolean  @default(false)\n  /// Routing line that priced the call: mode key, high-effort, turbo or classifier.\n  lineKey            String\n  provider           String\n  model              String\n  tokensIn           Int      @default(0)\n  tokensOut          Int      @default(0)\n  /// Coût de revient in millicents (1/1000 cent).\n  costMillicents     Int      @default(0)\n  /// Credits billed to the user, in cents (0 when billedToUser=false).\n  creditCents        Int      @default(0)\n  /// creditCents*1000 - costMillicents (negative = platform absorbed cost).\n  marginMillicents   Int      @default(0)\n  billedToUser       Boolean  @default(true)\n  routingCardVersion Int\n  /// chat | classifier | continuation…\n  source             String   @default(\"chat\")\n\n  @@index([createdAt])\n  @@index([lineKey, createdAt])\n  @@index([organizationId, createdAt])\n  @@index([projectId, createdAt])\n}\n\n/// Checkpoint PROJET coordonné (plan §15, CTR-CHECKPOINT) : barrière logique\n/// + snapshots par composant (FILES/DATABASE/POD optionnel) + manifeste visible\n/// seulement une fois TOUT vérifié sous la même barrière. Rien à voir avec\n/// AgentCheckpoint (facturation par requête agent).\nmodel ProjectCheckpoint {\n  id                String    @id @default(cuid())\n  projectId         String\n  state             String    @default(\"PREPARING\")\n  logicalBarrierId  String?\n  /// crash-consistent | UNKNOWN. `application-consistent` is NOT emitted: it\n  /// would require quiescing the in-pod writers (dev server, terminal, agent),\n  /// which the API-level barrier cannot reach. See CHECKPOINT_CONTRACT §Cohérence.\n  consistencyLevel  String?\n  /// { components: [{componentKind, snapshotId, hash, verified, …}], restoreCompatibility, dependenciesDeclared }\n  manifest          Json?\n  error             String?\n  expiresAt         DateTime?\n  createdByUserId   String?\n  /// Stable retry identity. A repeated key is accepted only when requestHash\n  /// matches; a different request with the same key is refused.\n  idempotencyKey    String?   @unique\n  requestHash       String?\n  /// Non-null only while this row owns the one active barrier for its project.\n  /// The unique constraint is the durable per-project singleton; an expired\n  /// owner is cleared under the same project lock before a successor acquires.\n  barrierProjectId  String?   @unique\n  barrierOwnerToken String?\n  barrierFence      Int       @default(0)\n  /// Barrier lease deadline. The write barrier is read from THIS COLUMN, not from\n  /// process memory: the API runs 2..6 replicas (values-prod.yaml), so an\n  /// in-process barrier is invisible to the other replicas and freezes nothing.\n  /// A past/NULL value means thawed — expiry IS the guaranteed thaw, even if the\n  /// process holding the checkpoint dies mid-flight.\n  barrierExpiresAt  DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  createdBy User?   @relation(\"ProjectCheckpointCreator\", fields: [createdByUserId], references: [id], onDelete: SetNull)\n\n  @@index([projectId, createdAt])\n  @@index([barrierProjectId, barrierExpiresAt])\n  @@index([state, createdAt])\n}\n\n/// A secure project remix (fork) run. Tracks the normative state machine\n/// (PENDING → SNAPSHOT_PINNED → CREDENTIALS_DETACHED → SOURCE_SANITIZED\n/// → CLONING → SCANNING → STORAGE_PINNED → STORAGE_POLICY_APPLIED\n/// → DATABASE_PINNED → DB_FORKING → INDEXING → COMPLETED) so the\n/// credentials-detached-before-cloning invariant is auditable. `detachedKeys`\n/// holds ONLY secret/env KEYS (references) — never a value. `scanFindings`\n/// records materialized-secret hits (key + location, never the value).\nmodel RemixJob {\n  id                       String             @id @default(cuid())\n  sourceProjectId          String\n  targetProjectId          String?\n  organizationId           String\n  actorUserId              String?\n  state                    String             @default(\"PENDING\")\n  /// Tenant-scoped retry key. Legacy rows may be null; every new API job has one.\n  idempotencyKey           String?\n  /// SHA-256 of the non-secret, authorization-relevant request shape.\n  requestHash              String?\n  /// Optimistic-concurrency fence for state/ownership transitions.\n  version                  Int                @default(0)\n  /// Fencing token and renewable lease held by the current executor.\n  operationToken           String?\n  operationExpiresAt       DateTime?\n  /// IMMUTABLE source release the clone reproduces. When set, CLONING reads the\n  /// files from this pinned ProjectSnapshot archive (not the live source), so a\n  /// gallery remix is reproducible from the exact published release. NULL for a\n  /// legacy live-source remix. This is the provenance pin (I-RMX-PIN).\n  sourceSnapshotId         String?\n  /// SHA-256 of the pinned ProjectSnapshot archive bytes.\n  sourceSnapshotHash       String?\n  /// The gallery listing this remix was launched from, if any (provenance).\n  sourceListingId          String?\n  /// { secretKeys: string[], envVarKeys: string[] } — references only.\n  detachedKeys             Json?\n  /// DETACH | CLONE | SHARE_WITH_CONSENT\n  storagePolicy            String             @default(\"DETACH\")\n  /// Versioned explicit consent for SHARE_WITH_CONSENT; null for other policies.\n  storageConsentVersion    String?\n  /// Redacted per-object source/target verification facts (key,size,generation,hash).\n  storageInventory         Json?\n  /// Read-only source binding created for SHARE_WITH_CONSENT.\n  storageShareId           String?\n  /// SecretScanFinding[] { path, secretKey, line } — never the value.\n  scanFindings             Json?\n  /// Count of value-lines scrubbed out of the clone during CLONING.\n  scrubbedCount            Int                @default(0)\n  /// VERSIONED license captured at remix time from the source listing —\n  /// { licenseId, licenseTextSha256, sourceListingId, capturedAt }. Immutable on\n  /// the job: later edits to the listing's license never rewrite what THIS remix\n  /// was accepted under (I-RMX-3, P0-V3-05). Null for a same-org self-remix.\n  licenseSnapshot          Json?\n  /// Version of the remix consent text the REMIXER explicitly accepted before\n  /// the clone ran (REMIX_CONSENT_VERSION at accept time). Null = no consent\n  /// captured (same-org self-remix only — a gallery remix REQUIRES it).\n  consentVersion           String?\n  /// PiiFinding[] { path, kind, line } — kind of PII masked, never the value.\n  piiFindings              Json?\n  /// Count of PII spans masked out of the clone during SOURCE_SANITIZED.\n  piiMaskedCount           Int                @default(0)\n  /// Honest marker: was a physical isolated DB provisioned, or deferred?\n  dbForked                 Boolean            @default(false)\n  /// { instanceId, environment, targetTime, lsn? } — never a connection URI.\n  sourceDatabasePin        Json?\n  /// Target DatabaseInstance row while the isolated CNPG recovery is running.\n  targetDatabaseInstanceId String?\n  /// Desired terminal state while physical cleanup is in progress.\n  cleanupTerminalState     String?\n  /// Stable public code; `error` remains a redacted user-facing message.\n  errorCode                String?\n  error                    String?\n  createdAt                DateTime           @default(now())\n  updatedAt                DateTime           @updatedAt\n  targetProject            Project?           @relation(\"RemixJobTarget\", fields: [targetProjectId], references: [id], onDelete: SetNull)\n  targetDatabaseInstance   DatabaseInstance?  @relation(\"RemixJobTargetDatabase\", fields: [targetDatabaseInstanceId], references: [id], onDelete: SetNull)\n  storageShare             RemixStorageShare? @relation(\"RemixJobStorageShare\", fields: [storageShareId], references: [id], onDelete: SetNull)\n\n  @@unique([organizationId, idempotencyKey])\n  @@index([sourceProjectId])\n  @@index([organizationId, createdAt])\n  @@index([targetProjectId])\n  @@index([state, operationExpiresAt])\n}\n\n/// Explicit read-only object-storage sharing created by a remix. The source\n/// bucket is never inferred from project lineage: without this durable,\n/// versioned consent row, a target project cannot read source objects.\nmodel RemixStorageShare {\n  id                   String       @id @default(cuid())\n  sourceProjectId      String\n  targetProjectId      String       @unique\n  sourceOrganizationId String\n  targetOrganizationId String\n  consentVersion       String\n  consentedByUserId    String?\n  consentedAt          DateTime     @default(now())\n  sourceInventory      Json\n  state                String       @default(\"ACTIVE\")\n  revokedAt            DateTime?\n  createdAt            DateTime     @default(now())\n  updatedAt            DateTime     @updatedAt\n  sourceProject        Project      @relation(\"RemixStorageShareSourceProject\", fields: [sourceProjectId], references: [id], onDelete: Cascade)\n  targetProject        Project      @relation(\"RemixStorageShareTargetProject\", fields: [targetProjectId], references: [id], onDelete: Cascade)\n  sourceOrganization   Organization @relation(\"RemixStorageShareSourceOrganization\", fields: [sourceOrganizationId], references: [id], onDelete: Cascade)\n  targetOrganization   Organization @relation(\"RemixStorageShareTargetOrganization\", fields: [targetOrganizationId], references: [id], onDelete: Cascade)\n  consentedBy          User?        @relation(\"RemixStorageShareConsentedBy\", fields: [consentedByUserId], references: [id], onDelete: SetNull)\n  remixJobs            RemixJob[]   @relation(\"RemixJobStorageShare\")\n\n  @@index([sourceProjectId])\n  @@index([sourceOrganizationId])\n  @@index([targetOrganizationId])\n}\n\n/// A secure project import run (DOMAIN_MODEL §2). Tracks the normative state\n/// machine (RECEIVED → STAGING_ISOLATED → SCANNING → QUARANTINED →\n/// AWAITING_USER_ACTION → COMMITTING → COMMITTED, with ROLLING_BACK / EXPIRED /\n/// CANCELLED cleanup branches). `findings` holds REDACTED secret findings only\n/// (never a raw value); `consent` records the per-finding keep/redact decision.\n/// `targetProjectId` is assigned while the unique COMMITTING claimant creates\n/// its target. It may therefore identify a partial target while cleanup is\n/// pending; COMMITTED is the only state in which that target is user-visible.\nmodel ImportJob {\n  id                   String    @id @default(cuid())\n  organizationId       String\n  actorUserId          String?\n  /// Client key, unique inside its tenant. This is the durable create authority.\n  idempotencyKey       String\n  /// SHA-256 of the non-secret request shape. Rejects key reuse for another input.\n  requestHash          String\n  /// One of the 12 hub tiles (github|bitbucket|vercel|figma|claude|bolt|lovable|base44|zip|spreadsheet|previous-agent-export|empty)\n  provider             String\n  state                String    @default(\"RECEIVED\")\n  sourceRef            String?\n  /// ImportSecretFinding[] { path, line, kind, preview } — redacted, no value.\n  findings             Json?\n  /// ConsentDecision { \"path:line\": \"keep\"|\"redact\" }.\n  consent              Json?\n  /// Set by the COMMITTING claimant; cleared after verified rollback cleanup.\n  targetProjectId      String?\n  /// Disposable, server-only staging. Never returned by the public job endpoint.\n  stagedFiles          Json?\n  /// Whitelisted connector facts only; credentials and tokens are never stored.\n  connectorPreview     Json?\n  stagedFileCount      Int       @default(0)\n  redactedCount        Int       @default(0)\n  /// E-CODE DECISION (not Replit parity): idempotent credit reservation marker.\n  creditsReserved      Boolean   @default(false)\n  /// Optimistic concurrency fence for every state transition.\n  version              Int       @default(0)\n  /// Fencing token held by a commit/cleanup claimant across replicas.\n  operationToken       String?\n  /// Reaper may steal an orphaned claim only after this durable lease expires.\n  operationExpiresAt   DateTime?\n  /// Terminal state to publish after CLEANUP_PENDING has really removed its target.\n  cleanupTerminalState String?\n  error                String?\n  expiresAt            DateTime?\n  createdAt            DateTime  @default(now())\n  updatedAt            DateTime  @updatedAt\n\n  organization  Organization             @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  actor         User?                    @relation(\"ImportJobActor\", fields: [actorUserId], references: [id], onDelete: SetNull)\n  targetProject Project?                 @relation(\"ImportJobTarget\", fields: [targetProjectId], references: [id], onDelete: SetNull)\n  /// Rolling-upgrade compatibility only. New imports reserve through LedgerReservation.\n  reservation   ImportCreditReservation?\n\n  @@unique([organizationId, idempotencyKey])\n  @@index([organizationId, createdAt])\n  @@index([targetProjectId])\n  @@index([state])\n}\n\n/// Legacy import credit hold retained only so jobs created before migration 0095\n/// can finish or clean up during a rolling deployment. New imports use the\n/// canonical double-entry LedgerReservation/Transaction/Entry lifecycle.\nmodel ImportCreditReservation {\n  id              String    @id @default(cuid())\n  organizationId  String\n  key             String\n  importJobId     String    @unique\n  reservedCredits Int\n  debitedCredits  Int       @default(0)\n  /// RESERVED | SETTLED | COMPENSATED\n  state           String    @default(\"RESERVED\")\n  version         Int       @default(0)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n  importJob       ImportJob @relation(fields: [importJobId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, key])\n  @@index([organizationId])\n}\n\n/// A curated public Gallery listing (TPL-02). Mirrors the CONFIRMED\n/// replit.com/gallery surface: a browsable grid of published apps with an\n/// author, public stats (views / uses), a category, a detail page, an outbound\n/// \"View App\" link, and a Remix CTA.\n///\n/// CURATION, NOT SELF-SERVICE. Per DEC-GALLERY-NO-SELF-PUBLISH (Replit's\n/// \"Submit your App\" is an external Typeform → human intake), rows are created\n/// by a curator/seed, never by an in-product self-service Publish button. The\n/// `status` gate is the curation boundary; only PUBLISHED rows are shown.\n///\n/// `sourceSnapshotId` pins the IMMUTABLE release a Remix reproduces — a\n/// ProjectSnapshot archive of the source project taken at curation time. Remix\n/// clones from THAT snapshot, so what a user forks matches the published\n/// listing regardless of later edits to the source project.\nmodel GalleryListing {\n  id                  String    @id @default(cuid())\n  slug                String    @unique\n  title               String\n  description         String\n  category            String\n  /// Free-form display tags ([\"react\",\"stripe\"]). Not a taxonomy.\n  tags                String[]  @default([])\n  /// PUBLISHED (visible) | PENDING_REVIEW (curated, not yet live) | UNPUBLISHED.\n  status              String    @default(\"PUBLISHED\")\n  featured            Boolean   @default(false)\n  sourceProjectId     String\n  /// Immutable release pin — the ProjectSnapshot a Remix reproduces.\n  sourceSnapshotId    String\n  /// Curated author display (denormalized so a listing survives author changes).\n  authorName          String\n  authorUserId        String?\n  /// Outbound \"View App\" link to the deployed app (may be null pre-deploy).\n  appUrl              String?\n  /// Card preview image (a real rendered screenshot). Root-relative static\n  /// asset (/gallery-apps/<id>/thumbnail.png) or an https URL; null renders\n  /// the text-only card.\n  thumbnailUrl        String?\n  /// FAIL-CLOSED (directive 20/07) : un projet publié ordinaire est\n  /// ALL_RIGHTS_RESERVED, non-remixable. remixAllowed ne passe true qu'avec\n  /// une licence EXPLICITE + confirmation des droits + politique PII acceptée.\n  remixAllowed        Boolean   @default(false)\n  /// License identifier declared at curation (e.g. an SPDX id like \"MIT\").\n  /// Null = the author declared no license (surfaced as such — never invented).\n  licenseId           String?\n  /// VERSIONED license text snapshot captured at curation. What a remixer\n  /// accepts is THIS text, pinned by its sha256 onto the RemixJob.\n  licenseText         String?\n  /// sha256 of licenseText — the version pin recorded on every remix.\n  licenseTextSha256   String?\n  /// Version of the PII-sharing consent the AUTHOR explicitly gave at curation\n  /// (data ships unmasked). Null = no consent → PII is masked on every remix.\n  piiConsentVersion   String?\n  /// TRACE AUDITABLE des confirmations exigées pour rendre un listing remixable\n  /// (P0-V3-05, réserve #8). Avant la migration 0081 elles étaient validées à la\n  /// curation puis JAMAIS écrites : la confirmation des droits par le curateur\n  /// était inauditable a posteriori. Horodatage + acteur (userId de l'admin qui\n  /// a curé). Null = jamais confirmé.\n  rightsConfirmedAt   DateTime?\n  rightsConfirmedBy   String?\n  piiPolicyAcceptedAt DateTime?\n  piiPolicyAcceptedBy String?\n  viewCount           Int       @default(0)\n  useCount            Int       @default(0)\n  createdAt           DateTime  @default(now())\n  publishedAt         DateTime?\n\n  sourceProject Project @relation(\"ProjectGalleryListings\", fields: [sourceProjectId], references: [id], onDelete: Cascade)\n  author        User?   @relation(\"UserGalleryListings\", fields: [authorUserId], references: [id], onDelete: SetNull)\n\n  @@index([status, category])\n  @@index([status, featured])\n  @@index([status, createdAt])\n}\n\n// ─────────────────────────────────────────────────────────────────────────────\n// CANONICAL DOUBLE-ENTRY LEDGER (C1 / P0-V3-12)\n// Supersedes the single-entry CreditWallet.balanceCents \"porte-monnaie\". Every\n// posted transaction balances per currency (Σ debits == Σ credits); posted\n// transactions + entries are IMMUTABLE (DB triggers in migration 0078) — a\n// correction is a NEW reversing transaction, never a mutation. Amounts are exact\n// integer minor units (BigInt); FX is exact rational (num/den). No relation to\n// Organization is declared (plain organizationId, like UsageReservation) to keep\n// the migration self-contained.\n// ─────────────────────────────────────────────────────────────────────────────\n\nenum LedgerAccountType {\n  ASSET\n  LIABILITY\n  REVENUE\n  EXPENSE\n  EQUITY\n}\n\nenum LedgerEntryDirection {\n  DEBIT\n  CREDIT\n}\n\nenum LedgerReservationStatus {\n  ACTIVE\n  COMMITTED\n  COMPENSATED\n  RELEASED\n  EXPIRED\n}\n\nenum LedgerReconciliationStatus {\n  OK\n  DISCREPANCY\n}\n\nmodel LedgerAccount {\n  id             String            @id @default(cuid())\n  organizationId String\n  /// Stable account key: user_credits | reserved | revenue | provider_cost |\n  /// fx_clearing | fx_rounding | tax_payable | refunds | budget_hold ...\n  key            String\n  type           LedgerAccountType\n  currency       String\n  createdAt      DateTime          @default(now())\n  entries        LedgerEntry[]\n\n  @@unique([organizationId, key, currency])\n  @@index([organizationId])\n}\n\nmodel LedgerTransaction {\n  id              String              @id @default(cuid())\n  organizationId  String\n  reason          String\n  /// Idempotency key (unique per org when set). NULL rows are not deduped.\n  idempotencyKey  String?\n  /// Compensation: points at the original transaction this one reverses.\n  reversalOfId    String?\n  rateCardVersion Int?\n  postedAt        DateTime            @default(now())\n  metadata        Json?\n  entries         LedgerEntry[]\n  reversalOf      LedgerTransaction?  @relation(\"LedgerReversal\", fields: [reversalOfId], references: [id], onDelete: SetNull)\n  reversals       LedgerTransaction[] @relation(\"LedgerReversal\")\n\n  @@unique([organizationId, idempotencyKey])\n  @@index([organizationId, postedAt])\n  @@index([reversalOfId])\n}\n\nmodel LedgerEntry {\n  id            String               @id @default(cuid())\n  transactionId String\n  accountId     String\n  direction     LedgerEntryDirection\n  /// Exact positive integer minor units (e.g. USD cents / micro-credits).\n  amountMinor   BigInt\n  currency      String\n  transaction   LedgerTransaction    @relation(fields: [transactionId], references: [id], onDelete: Cascade)\n  account       LedgerAccount        @relation(fields: [accountId], references: [id], onDelete: Cascade)\n\n  @@index([transactionId])\n  @@index([accountId, currency])\n}\n\nmodel LedgerReservation {\n  id              String                  @id @default(cuid())\n  organizationId  String\n  userId          String?\n  /// Idempotency key, unique per org: a replay returns the SAME reservation.\n  idempotencyKey  String\n  /// SHA-256 of the normalized business request. Reusing the key with another\n  /// amount, tenant, user, operation, rate card or import job fails closed.\n  requestHash     String?\n  operation       String\n  status          LedgerReservationStatus @default(ACTIVE)\n  /// Optimistic fencing generation, incremented on every lifecycle transition.\n  version         Int                     @default(0)\n  currency        String                  @default(\"usd\")\n  /// Authorized ceiling (hold, not a debit).\n  maxAmountMinor  BigInt\n  /// Actually settled at COMMIT (≤ maxAmountMinor).\n  committedMinor  BigInt?\n  rateCardVersion Int?\n  importJobId     String?\n  /// Correlated ledger transactions across the lifecycle.\n  reserveTxId     String?\n  settleTxId      String?\n  compensateTxId  String?\n  expiresAt       DateTime\n  committedAt     DateTime?\n  releasedAt      DateTime?\n  releaseReason   String?\n  metadata        Json?\n  createdAt       DateTime                @default(now())\n  updatedAt       DateTime                @updatedAt\n\n  @@unique([organizationId, idempotencyKey])\n  @@index([organizationId, status])\n  @@index([status, expiresAt])\n  @@index([importJobId])\n}\n\nmodel LedgerFxRate {\n  id           String    @id @default(cuid())\n  fromCurrency String\n  toCurrency   String\n  /// Exact rational rate = rateNum / rateDen (no float).\n  rateNum      BigInt\n  rateDen      BigInt\n  effectiveAt  DateTime\n  /// Exclusive upper bound this rate is valid for (cutoff).\n  cutoffAt     DateTime?\n  createdAt    DateTime  @default(now())\n\n  @@index([fromCurrency, toCurrency, effectiveAt])\n}\n\nmodel LedgerReconciliationRun {\n  id               String                     @id @default(cuid())\n  organizationId   String?\n  /// GCP | STRIPE | LEDGER — the external source compared against the ledger.\n  source           String\n  status           LedgerReconciliationStatus\n  discrepancyCount Int                        @default(0)\n  discrepancies    Json?\n  runAt            DateTime                   @default(now())\n  metadata         Json?\n\n  @@index([source, runAt])\n}\n\n// BLOCKER #5 — honest preview readiness. The in-preview reporter script detects a\n// blank DOM / console error the server can never see and beacons it. Persisting\n// it (vs the old fire-and-forget log) lets `/ports` readiness be honest across\n// API replicas: a fresh blank/error beacon vetoes `ready` even when the port\n// probe passed. `status`: 'ok' | 'blank' | 'error'. One row per (workspace,port),\n// upserted; readiness only honours beacons newer than a short TTL.\nmodel PreviewReadinessBeacon {\n  id          String    @id @default(cuid())\n  workspaceId String\n  port        Int\n  status      String\n  detail      String?\n  reportedAt  DateTime  @default(now())\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@unique([workspaceId, port])\n  @@index([workspaceId])\n}\n\n// BLOCKER #6 — timestamped workspace lifecycle machine. Append-only trail of\n// PENDING->STARTING->RUNNING->STOPPING->STOPPED/FAILED transitions so a workspace\n// that died can be reconstructed after the fact (vs Workspace.status, a single\n// overwritten value). `state` is a WorkspaceLifecycleState; transitions are\n// validated by assertWorkspaceLifecycleTransition before write.\nmodel WorkspaceLifecycleEvent {\n  id          String    @id @default(cuid())\n  workspaceId String\n  state       String\n  reason      String?\n  detail      Json?\n  at          DateTime  @default(now())\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId, at])\n}\n\n// BLOCKER #6 — post-mortem snapshot captured when a workspace stops/fails: the\n// last-known ports, processes, Problems (beacons/diagnostics) and a tail of the\n// runtime logs, frozen at shutdown. Append-only (one per stop), so a support\n// operator can see WHY a preview was blank/dead after the pod is gone.\nmodel WorkspacePostMortem {\n  id          String    @id @default(cuid())\n  workspaceId String\n  reason      String\n  finalState  String\n  ports       Json?\n  processes   Json?\n  problems    Json?\n  logsTail    String?\n  capturedAt  DateTime  @default(now())\n  workspace   Workspace @relation(fields: [workspaceId], references: [id], onDelete: Cascade)\n\n  @@index([workspaceId, capturedAt])\n}\n\n// ─── CloudTenant / Project Factory / Platform IAM ────────────────────────────\n// These rows are the durable control-plane record. External GCP effects are\n// always driven through CloudOperation, whose DB-clock lease and fencing token\n// make retries and takeover safe across API replicas.\n\nenum CloudTenantBoundaryType {\n  PERSON\n  WORKSPACE\n  LEGAL_ENTITY\n  BILLING_ACCOUNT\n}\n\nenum CloudTenantLifecycle {\n  PROVISIONING\n  ACTIVE\n  SUSPENDED\n  MERGED\n  CLOSED\n}\n\nenum CloudProjectBindingRole {\n  PRIMARY\n  REGION_SHARD\n  QUOTA_SHARD\n  MIGRATION_TARGET\n}\n\nenum CloudProjectBindingState {\n  REQUESTED\n  CREATING\n  BILLING_LINKED\n  APIS_ENABLING\n  SERVICE_AGENTS_READY\n  IAM_BOUND\n  EDGE_READY\n  ACTIVE\n  BILLING_SUSPENDED\n  QUOTA_EXHAUSTED\n  DRIFT_DETECTED\n  DELETE_REQUESTED\n  RECOVERY_WINDOW\n  RESTORING\n  PURGING\n  PURGED\n}\n\nenum CloudTenantTransferState {\n  REQUESTED\n  REVOKING\n  REVOKED\n  REGRANTING\n  COMPLETED\n  FAILED\n}\n\nenum CloudOperationKind {\n  TENANT_CREATE\n  PROJECT_BIND\n  TENANT_SUSPEND\n  TENANT_RESTORE\n  TENANT_MERGE\n  TENANT_SPLIT\n  TENANT_TRANSFER\n  PROJECT_ADVANCE\n  TEARDOWN_REQUEST\n  TEARDOWN_EXECUTE\n  TEARDOWN_VERIFY\n  PROJECT_RESTORE\n  PROJECT_PURGE\n  IAM_ENSURE\n}\n\nenum CloudOperationStatus {\n  PENDING\n  RUNNING\n  WAITING\n  SUCCEEDED\n  FAILED\n  CANCELLED\n}\n\nenum CloudTeardownStatus {\n  INVENTORYING\n  DELETING\n  VERIFYING\n  COMPLETE\n  ORPHANS_DETECTED\n  FAILED\n}\n\nenum PlatformIamIdentityKind {\n  BUILD\n  PROMOTION\n  RUNTIME\n}\n\nenum PlatformIamComplianceStatus {\n  UNKNOWN\n  COMPLIANT\n  KEY_DRIFT\n  DISABLED\n}\n\nmodel CloudTenant {\n  id                   String                  @id @default(cuid())\n  // Direct product-domain link. Null is reserved for platform/system tenants;\n  // customer tenants are created with an Organization id by the admin API.\n  organizationId       String?                 @unique\n  customerBoundaryType CloudTenantBoundaryType\n  ownerPrincipalId     String\n  billingPrincipalId   String\n  billingAccountId     String\n  legalEntityId        String?\n  residencyPolicy      String                  @default(\"eu\")\n  lifecycle            CloudTenantLifecycle    @default(ACTIVE)\n  suspensionReason     String?\n  suspensionEvidence   Json?\n  // Version fences every topology mutation; ownershipVersion changes only\n  // when ownership itself changes (transfer/merge/split provenance).\n  version              Int                     @default(1)\n  ownershipVersion     Int                     @default(1)\n  mergedIntoTenantId   String?\n  splitFromTenantId    String?\n  createdAt            DateTime                @default(now())\n  updatedAt            DateTime                @updatedAt\n\n  organization      Organization?         @relation(fields: [organizationId], references: [id], onDelete: Restrict)\n  mergedInto        CloudTenant?          @relation(\"CloudTenantMerge\", fields: [mergedIntoTenantId], references: [id], onDelete: Restrict)\n  mergedSources     CloudTenant[]         @relation(\"CloudTenantMerge\")\n  splitFrom         CloudTenant?          @relation(\"CloudTenantSplit\", fields: [splitFromTenantId], references: [id], onDelete: Restrict)\n  splitChildren     CloudTenant[]         @relation(\"CloudTenantSplit\")\n  bindings          CloudProjectBinding[]\n  transfers         CloudTenantTransfer[]\n  operations        CloudOperation[]      @relation(\"CloudOperationTenant\")\n  relatedOperations CloudOperation[]      @relation(\"CloudOperationRelatedTenant\")\n\n  @@index([lifecycle])\n  @@index([ownerPrincipalId])\n}\n\nmodel CloudProjectBinding {\n  id                   String                   @id @default(cuid())\n  cloudTenantId        String\n  // Optional direct link to the published Vibecore project. A project can be\n  // attached to at most one GCP binding, and the service verifies that its\n  // Organization matches the tenant before committing the link.\n  projectId            String?                  @unique\n  gcpProjectId         String                   @unique\n  gcpProjectNumber     String?                  @unique\n  role                 CloudProjectBindingRole\n  region               String\n  state                CloudProjectBindingState @default(REQUESTED)\n  parentFolderId       String?\n  quotas               Json?\n  billingLabels        Json?\n  capacityPolicy       Json?\n  reconciliationStatus String                   @default(\"UNKNOWN\")\n  recoveryWindowEndsAt DateTime?\n  version              Int                      @default(1)\n  createdAt            DateTime                 @default(now())\n  updatedAt            DateTime                 @updatedAt\n\n  tenant     CloudTenant                @relation(fields: [cloudTenantId], references: [id], onDelete: Restrict)\n  project    Project?                   @relation(fields: [projectId], references: [id], onDelete: Restrict)\n  events     CloudProjectFactoryEvent[]\n  teardowns  CloudTeardownRecord[]\n  identities PlatformIamIdentity[]\n  operations CloudOperation[]\n\n  @@index([cloudTenantId, state])\n  @@index([state])\n  @@index([parentFolderId])\n}\n\nmodel CloudProjectFactoryEvent {\n  id          String   @id @default(cuid())\n  bindingId   String\n  operationId String?\n  fromState   String?\n  toState     String\n  actorUserId String?\n  detail      Json?\n  createdAt   DateTime @default(now())\n\n  binding   CloudProjectBinding @relation(fields: [bindingId], references: [id], onDelete: Restrict)\n  operation CloudOperation?     @relation(fields: [operationId], references: [id], onDelete: Restrict)\n\n  @@index([bindingId, createdAt])\n  @@index([operationId])\n}\n\nmodel CloudOperation {\n  id                String               @id @default(cuid())\n  idempotencyKey    String               @unique\n  requestHash       String\n  kind              CloudOperationKind\n  status            CloudOperationStatus @default(PENDING)\n  tenantId          String?\n  relatedTenantId   String?\n  bindingId         String?\n  actorUserId       String?\n  reauthenticatedAt DateTime?\n  step              String               @default(\"REQUESTED\")\n  payload           Json\n  checkpoint        Json?\n  result            Json?\n  leaseOwner        String?\n  leaseExpiresAt    DateTime?\n  fence             Int                  @default(0)\n  version           Int                  @default(0)\n  attempts          Int                  @default(0)\n  nextAttemptAt     DateTime             @default(now())\n  lastErrorCode     String?\n  lastErrorMessage  String?\n  completedAt       DateTime?\n  createdAt         DateTime             @default(now())\n  updatedAt         DateTime             @updatedAt\n\n  tenant            CloudTenant?               @relation(\"CloudOperationTenant\", fields: [tenantId], references: [id], onDelete: Restrict)\n  relatedTenant     CloudTenant?               @relation(\"CloudOperationRelatedTenant\", fields: [relatedTenantId], references: [id], onDelete: Restrict)\n  binding           CloudProjectBinding?       @relation(fields: [bindingId], references: [id], onDelete: Restrict)\n  actor             User?                      @relation(fields: [actorUserId], references: [id], onDelete: SetNull)\n  events            CloudOperationEvent[]\n  transfer          CloudTenantTransfer?\n  factoryEvents     CloudProjectFactoryEvent[]\n  requestedTeardown CloudTeardownRecord?\n\n  @@index([status, nextAttemptAt])\n  @@index([tenantId, createdAt])\n  @@index([relatedTenantId, createdAt])\n  @@index([bindingId, createdAt])\n}\n\nmodel CloudOperationEvent {\n  id          String   @id @default(cuid())\n  operationId String\n  fence       Int\n  type        String\n  detail      Json?\n  createdAt   DateTime @default(now())\n\n  operation CloudOperation @relation(fields: [operationId], references: [id], onDelete: Restrict)\n\n  @@index([operationId, createdAt])\n}\n\nmodel CloudTenantTransfer {\n  id                       String                   @id @default(cuid())\n  operationId              String                   @unique\n  cloudTenantId            String\n  expectedOwnershipVersion Int\n  fromPrincipalId          String\n  toPrincipalId            String\n  grantRoles               Json\n  state                    CloudTenantTransferState @default(REQUESTED)\n  revokeEvidence           Json?\n  revokeVerifiedAt         DateTime?\n  regrantEvidence          Json?\n  version                  Int                      @default(0)\n  errorCode                String?\n  errorMessage             String?\n  completedAt              DateTime?\n  createdAt                DateTime                 @default(now())\n  updatedAt                DateTime                 @updatedAt\n\n  operation CloudOperation @relation(fields: [operationId], references: [id], onDelete: Restrict)\n  tenant    CloudTenant    @relation(fields: [cloudTenantId], references: [id], onDelete: Restrict)\n\n  @@index([cloudTenantId, createdAt])\n  @@index([state])\n}\n\nmodel CloudTeardownRecord {\n  id                 String              @id @default(cuid())\n  bindingId          String\n  requestOperationId String              @unique\n  status             CloudTeardownStatus @default(INVENTORYING)\n  resourceInventory  Json?\n  erasureProof       Json?\n  orphans            Json?\n  version            Int                 @default(0)\n  startedAt          DateTime            @default(now())\n  completedAt        DateTime?\n\n  binding          CloudProjectBinding @relation(fields: [bindingId], references: [id], onDelete: Restrict)\n  requestOperation CloudOperation      @relation(fields: [requestOperationId], references: [id], onDelete: Restrict)\n\n  @@index([bindingId, startedAt])\n}\n\nmodel PlatformIamIdentity {\n  id                     String                      @id @default(cuid())\n  bindingId              String?\n  kind                   PlatformIamIdentityKind\n  app                    String                      @default(\"\")\n  environment            String                      @default(\"\")\n  privilegeBoundary      String\n  gcpProjectId           String\n  gcpServiceAccountEmail String                      @unique\n  persistentKeys         Int                         @default(0)\n  complianceStatus       PlatformIamComplianceStatus @default(UNKNOWN)\n  revisionsServed        Int                         @default(0)\n  version                Int                         @default(0)\n  lastRotatedAt          DateTime?\n  lastUsedAt             DateTime?\n  createdAt              DateTime                    @default(now())\n  updatedAt              DateTime                    @updatedAt\n\n  binding        CloudProjectBinding?            @relation(fields: [bindingId], references: [id], onDelete: Restrict)\n  impersonations PlatformIamImpersonationAudit[]\n\n  @@unique([kind, app, environment, privilegeBoundary, gcpProjectId])\n  @@index([gcpProjectId, kind])\n  @@index([bindingId])\n}\n\nmodel PlatformIamImpersonationAudit {\n  id                   String   @id @default(cuid())\n  identityId           String\n  actorPrincipal       String\n  purpose              String\n  tokenLifetimeSeconds Int\n  createdAt            DateTime @default(now())\n\n  identity PlatformIamIdentity @relation(fields: [identityId], references: [id], onDelete: Restrict)\n\n  @@index([identityId, createdAt])\n}\n\n/// Durable, resumable execution plan for one account purge. The row deliberately\n/// has no User foreign key: the receipt and effect history must outlive the\n/// subject's anonymisation. Only one plan can ever target a subject.\nmodel PurgePlan {\n  id                  String             @id @default(cuid())\n  userId              String             @unique\n  ownerToken          String             @unique\n  status              String             @default(\"ACTIVE\")\n  version             Int                @default(0)\n  leaseExpiresAt      DateTime\n  requestedAt         DateTime\n  purgeDueAt          DateTime\n  topologyFingerprint String\n  inventory           Json\n  correlationId       String?\n  lastErrorCode       String?\n  startedAt           DateTime           @default(now())\n  completedAt         DateTime?\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n  freezes             PurgeFreeze[]\n  effects             PurgeEffect[]\n  receipt             PurgeReceipt?\n  workspaceRuntimes   WorkspaceRuntime[]\n\n  @@index([status, leaseExpiresAt])\n  @@index([correlationId])\n}\n\n/// Per-plan ownership of topology freezes. A resource remains frozen while any\n/// active plan owns a row for it; releasing one plan never thaws another.\nmodel PurgeFreeze {\n  id           String    @id @default(cuid())\n  planId       String\n  resourceType String\n  resourceId   String\n  createdAt    DateTime  @default(now())\n  plan         PurgePlan @relation(fields: [planId], references: [id], onDelete: Cascade)\n\n  @@unique([resourceType, resourceId, planId])\n  @@index([resourceType, resourceId])\n  @@index([planId])\n}\n\n/// Durable idempotency receipt for every physical side effect. A succeeded key\n/// is never executed twice by a resumed/reclaimed plan; failed effects retain a\n/// bounded diagnostic and can be retried safely.\nmodel PurgeEffect {\n  id            String    @id @default(cuid())\n  planId        String\n  effectKey     String\n  resourceType  String\n  resourceId    String\n  status        String    @default(\"PENDING\")\n  attempt       Int       @default(0)\n  receipt       Json?\n  lastErrorCode String?\n  startedAt     DateTime?\n  completedAt   DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n  plan          PurgePlan @relation(fields: [planId], references: [id], onDelete: Cascade)\n\n  @@unique([planId, effectKey])\n  @@index([planId, status])\n  @@index([resourceType, resourceId])\n}\n\n/// Immutable proof written in the same transaction as the account tombstone.\n/// Queue removal is allowed only after this row exists.\nmodel PurgeReceipt {\n  userId    String    @id\n  planId    String    @unique\n  purgedAt  DateTime\n  proof     Json\n  createdAt DateTime  @default(now())\n  plan      PurgePlan @relation(fields: [planId], references: [id], onDelete: Restrict)\n\n  @@index([purgedAt])\n}\n"
}

